# SECTION: skillsdb.core.concurrency
# =====================================================================
def resolve_optimal_workers(db_path: Path = DB_PATH) -> int:
    """Dynamically resolves ThreadPoolExecutor worker count from active account and model tier (16 on Ultra, 8 on Pro, 1 on Local/Offline)."""
    try:
        info = detect_model_and_pool(db_path=db_path)
        m_tier = info.get("model_tier", TIER_STANDARD)
        acc_tier = info.get("account_tier", "ultra")
        if m_tier in (TIER_LOCAL, TIER_OFFLINE):
            return 1
        if acc_tier == "ultra" or m_tier == TIER_ULTRA:
            return 16
        if acc_tier == "pro" or m_tier == TIER_STANDARD:
            return 8
    except Exception:
        pass
    return 8


def extract_skill_sections(content: str) -> list[dict]:
    """Parses markdown headers into sections with estimated token counts."""
    lines = content.splitlines()
    sections = []
    current_title = "Overview"
    current_level = 1
    current_lines = []

    in_fm = False
    body_lines = []
    for idx, line in enumerate(lines):
        if idx == 0 and line.strip() == "---":
            in_fm = True
            continue
        if in_fm:
            if line.strip() == "---":
                in_fm = False
            continue
        body_lines.append(line)

    in_fence = False
    for line in body_lines:
        if re.match(r"^\s*(`{3,}|~{3,})", line):
            in_fence = not in_fence
            current_lines.append(line)
            continue
        header_match = re.match(r"^(#{1,6})\s+(.+)$", line) if not in_fence else None
        if header_match:
            if current_lines:
                sec_text = "\n".join(current_lines).strip()
                if sec_text:
                    sections.append({
                        "level": current_level,
                        "title": current_title,
                        "content": sec_text,
                        "tokens": estimate_tokens(sec_text)
                    })
            current_level = len(header_match.group(1))
            current_title = header_match.group(2).strip()
            current_lines = [line]
        else:
            current_lines.append(line)

    if current_lines:
        sec_text = "\n".join(current_lines).strip()
        if sec_text:
            sections.append({
                "level": current_level,
                "title": current_title,
                "content": sec_text,
                "tokens": estimate_tokens(sec_text)
            })

    return sections


def fetch_single_skill(skill_name: str, db_path: Path = DB_PATH, summary: bool = False, section: str = None) -> dict:
    """Thread-safe single skill reader for parallel executors."""
    if not skill_name or not str(skill_name).strip("_% "):
        return {"name": skill_name, "found": False, "content": None, "token_estimate": 0, "tokens": 0}
    esc = str(skill_name).replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
    conn = get_thread_connection(db_path)
    try:
        cursor = conn.cursor()
        cursor.execute("""
        SELECT name, plugin_name, category, description, content, token_estimate
        FROM skills
        WHERE is_active = 1 AND (name = ? OR name LIKE ? ESCAPE '\\')
        ORDER BY CASE WHEN name = ? THEN 0 ELSE 1 END
        LIMIT 1;
        """, (skill_name, f"%{esc}%", skill_name))
        row = cursor.fetchone()
    finally:
        conn.close()
    if not row:
        return {"name": skill_name, "found": False, "content": None, "token_estimate": 0, "tokens": 0}

    content = row["content"]
    tokens = row["token_estimate"]
    if summary:
        sections = extract_skill_sections(content)
        sec_list = "\n".join([f"  * {s['title']} (~{s['tokens']} tokens)" for s in sections])
        content = f"# Skill Summary: {row['name']} ({row['plugin_name']})\nDescription: {row['description']}\n\nSections:\n{sec_list}"
        tokens = estimate_tokens(content)
    elif section:
        sections = extract_skill_sections(content)
        matched = next((s for s in sections if section.lower() in s["title"].lower()), None)
        if matched:
            content = f"# Skill: {row['name']} > {matched['title']}\n\n{matched['content']}"
            tokens = matched["tokens"]

    return {
        "name": row["name"],
        "plugin_name": row["plugin_name"],
        "category": row["category"],
        "description": row["description"],
        "token_estimate": tokens,
        "tokens": tokens,
        "found": True,
        "content": content
    }


def get_skills_parallel(skill_names: list[str], max_workers: int = None, as_json: bool = False, summary: bool = False, db_path: Path = DB_PATH) -> list[dict]:
    """Retrieves multiple skills concurrently using ThreadPoolExecutor under SQLite WAL mode."""
    workers = max_workers if (max_workers is not None and max_workers > 0) else resolve_optimal_workers(db_path)
    unique_names = list(dict.fromkeys(skill_names))
    indexed_results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(len(unique_names) or 1, workers)) as executor:
        future_to_info = {executor.submit(fetch_single_skill, name, db_path, summary): (idx, name) for idx, name in enumerate(unique_names)}
        for future in concurrent.futures.as_completed(future_to_info):
            idx, name = future_to_info[future]
            try:
                indexed_results.append((idx, future.result()))
            except Exception as e:
                indexed_results.append((idx, {"name": name, "found": False, "error": str(e), "token_estimate": 0, "tokens": 0, "content": None}))

    indexed_results.sort(key=lambda pair: pair[0])
    results = [pair[1] for pair in indexed_results]

    if as_json:
        print(json.dumps(results, indent=2))
        return results

    total_tokens = sum(r.get("token_estimate", 0) for r in results if r.get("found"))
    print(f"\n=== Batch Skills Retrieval ({len(results)} skills, ~{total_tokens} tokens total) ===\n")
    for r in results:
        if r.get("found"):
            print(f"--- Skill: {r['name']} (Plugin: {r['plugin_name']}, ~{r['token_estimate']} tokens) ---")
            print(r["content"])
            print("-" * 60 + "\n")
        else:
            print(f"--- Skill: {r['name']} [NOT FOUND] ---\n")
    return results


def search_single_query(query: str, db_path: Path = DB_PATH, limit: int = 4) -> list[dict]:
    """Thread-safe FTS5 search query."""
    words = [
        w for w in re.findall(r"[a-zA-Z0-9äöüÄÖÜß_]{2,}", (query or "").lower())
        if w not in ("and", "or", "not", "near")
    ]
    if not words:
        return []
    fts_query = " OR ".join(f'"{w}"' for w in words[:10])
    conn = get_thread_connection(db_path)
    try:
        cursor = conn.cursor()
        cursor.execute("""
        SELECT s.name, s.plugin_name, s.category, s.description, s.token_estimate, rank
        FROM skills_fts f
        JOIN skills s ON f.rowid = s.id
        WHERE skills_fts MATCH ? AND s.is_active = 1
        ORDER BY rank
        LIMIT ?;
        """, (fts_query, limit))
        rows = cursor.fetchall()
    finally:
        conn.close()
    return [{"name": r["name"], "plugin": r["plugin_name"], "category": r["category"], "description": r["description"] or "", "tokens": r["token_estimate"]} for r in rows]


def search_multi_parallel(queries: list[str], max_workers: int = None, limit_per_query: int = 4, as_json: bool = False, db_path: Path = DB_PATH) -> dict:
    """Executes multiple full-text search queries concurrently."""
    workers = max_workers if (max_workers is not None and max_workers > 0) else resolve_optimal_workers(db_path)
    all_results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(len(queries) or 1, workers)) as executor:
        future_to_q = {executor.submit(search_single_query, q, db_path, limit_per_query): q for q in queries}
        for future in concurrent.futures.as_completed(future_to_q):
            q = future_to_q[future]
            try:
                all_results[q] = future.result()
            except Exception as e:
                all_results[q] = [{"error": str(e)}]

    if as_json:
        print(json.dumps(all_results, indent=2))
        return all_results

    print(f"\n=== Multi-Query Parallel FTS5 Search ({len(queries)} queries) ===\n")
    for q in queries:
        matches = all_results.get(q, [])
        print(f"Results for query: '{q}' ({len(matches)} matches)")
        if matches:
            for m in matches:
                if "error" in m:
                    print(f"  * Error: {m['error']}")
                else:
                    desc_snip = (m.get("description") or "")[:80]
                    print(f"  * [{m['plugin']}] {m['name']} (~{m['tokens']} tokens) - {desc_snip}...")
        else:
            print("  * No matches.")
        print()
    return all_results


def get_cluster(domain: str, max_workers: int = None, as_json: bool = False, summary: bool = False, db_path: Path = DB_PATH):
    """Retrieves all pre-indexed skills belonging to a domain cluster concurrently in a single call."""
    dom_clean = domain.strip().lower()
    if dom_clean not in SKILL_CLUSTERS:
        if as_json:
            print("[]")
        else:
            print(f"Error: Unknown skill cluster '{domain}'. Available clusters: {', '.join(SKILL_CLUSTERS.keys())}")
        return []

    workers = max_workers if (max_workers is not None and max_workers > 0) else resolve_optimal_workers(db_path)
    tier_banner = "Ultra Concurrency" if workers >= 16 else f"Pro Concurrency ({workers} threads)"
    cluster_skills = SKILL_CLUSTERS[dom_clean]
    if not as_json:
        print(f"[{tier_banner}] Prefetching complete '{dom_clean}' cluster ({len(cluster_skills)} skills: {', '.join(cluster_skills)})...\n")
    return get_skills_parallel(cluster_skills, max_workers=workers, as_json=as_json, summary=summary, db_path=db_path)


def benchmark_concurrency(num_queries: int = 20, max_workers: int = None, db_path: Path = DB_PATH):
    """Compares sequential vs. parallel multi-query throughput on customizations.db."""
    workers = max_workers if (max_workers is not None and max_workers > 0) else resolve_optimal_workers(db_path)
    conn = get_connection(db_path)
    try:
        cursor = conn.cursor()
        cursor.execute("SELECT name FROM skills ORDER BY id LIMIT ?;", (num_queries,))
        names = [r[0] for r in cursor.fetchall()]
    finally:
        conn.close()

    if not names:
        print("Not enough skills in database for benchmark.")
        return

    print(f"\n================ SKILLSDB CONCURRENCY BENCHMARK ================")
    print(f"Dataset: {len(names)} skills | Max ThreadPool Workers: {workers}")

    # Sequential benchmark
    start_seq = time.perf_counter()
    for name in names:
        fetch_single_skill(name, db_path, summary=True)
    seq_duration = time.perf_counter() - start_seq
    print(f"Sequential Execution Time: {seq_duration * 1000:.2f} ms ({len(names) / (seq_duration or 0.001):.1f} queries/sec)")

    # Parallel benchmark
    start_par = time.perf_counter()
    unique_names = list(dict.fromkeys(names))
    with concurrent.futures.ThreadPoolExecutor(max_workers=min(len(unique_names) or 1, workers)) as executor:
        list(executor.map(lambda n: fetch_single_skill(n, db_path, summary=True), unique_names))
    par_duration = time.perf_counter() - start_par
    print(f"Parallel Execution Time:   {par_duration * 1000:.2f} ms ({len(names) / (par_duration or 0.001):.1f} queries/sec)")

    speedup = seq_duration / par_duration if par_duration > 0 else 1.0
    print(f"High-Concurrency Speedup:  {speedup:.2f}x faster with ThreadPoolExecutor")
    print("=================================================================\n")


# =====================================================================
# SECTION: skillsdb.core.guardrails
# =====================================================================
# Invariant characters
EM_DASH = "\u2014"
EN_DASH = "\u2013"

# Emoji Unicode ranges (Pictographs, symbols, supplementary planes)
EMOJI_PATTERN = re.compile(
    r"[\U00010000-\U0010ffff]"
    r"|[\u2600-\u27BF]"
    r"|[\u2300-\u23FF]"
    r"|[\u2B50-\u2B55]"
    r"|[\u203C-\u2049]"
)

# Deppenbindestrich patterns in German compound nouns (compounds that must not use hyphens)
DEPPENBINDESTRICH_PATTERN = re.compile(
    r"\b(?:"
    r"Token|Browser|Tab|Kontext|Subagenten|Abteilungs|Standard|Sitzungs|"
    r"Produktions|Speicher|Projekt|Entwickler|System|Architektur|Benchmark|"
    r"Changelog|Release|Reallife|Test|Unittest|Code|Skript|Prompt|Daten"
    r")-(?:"
    r"Reduktion|Tool|Wechsel|Kompaktierung|Isolation|Kontingent|Einstellung|"
    r"Dauer|Daten|Manager|Speicher|Fakten|Entscheidungen|Regeln|Protokoll|"
    r"Vergleich|Ersparnis|Suite|Ausführung|Verifikation|Analyse|Status|"
    r"Invariante|Muster|Board|Schranke"
    r")\b",
    re.IGNORECASE
)

# Secret and credential leak patterns
SECRET_PATTERNS = [
    ("OpenAI API Key", re.compile(r"\bsk-[a-zA-Z0-9_\-]{20,}\b")),
    ("OpenAI Project API Key", re.compile(r"\bsk-proj-[a-zA-Z0-9_\-]{20,}\b")),
    ("GitHub Personal Access Token", re.compile(r"\bgh[pousr]-[a-zA-Z0-9]{36,}\b")),
    ("AWS Access Key ID", re.compile(r"\bAKIA[0-9A-Z]{16}\b")),
    ("Private Key Header", re.compile(r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----")),
    (
        "Hardcoded Personal or Corporate Identifier",
        re.compile(
            r"\b(?:"
            + "moerth" + "j"
            + r"|"
            + "atli" + "west"
            + r"|"
            + "itx000" + "133"
            + r"|"
            + "fileserver" + "02"
            + r")\b",
            re.IGNORECASE,
        ),
    ),
]

SKIP_EXTENSIONS = {
    ".exe", ".dll", ".so", ".dylib", ".bin", ".obj", ".o", ".pyc",
    ".db", ".db-wal", ".db-shm", ".sqlite", ".sqlite3",
    ".png", ".jpg", ".jpeg", ".gif", ".ico", ".pdf", ".zip", ".tar", ".gz"
}

SKIP_DIRS = {
    ".git", ".agents", "__pycache__", ".venv", "venv", "node_modules", ".idea", ".vscode"
}


def check_text(text: str, filename: str = "<memory>") -> List[Dict[str, Any]]:
    """Checks a string against all deterministic guardrail invariants."""
    violations = []
    lines = text.splitlines()
    seen_changelog_versions = set()

    for idx, line in enumerate(lines, 1):
        # 1. Em-dash and En-dash invariant
        if EM_DASH in line or EN_DASH in line:
            dash_type = "Em-dash (U+2014)" if EM_DASH in line else "En-dash (U+2013)"
            violations.append({
                "file": filename,
                "line": idx,
                "rule": "no-dash-invariants",
                "severity": "CRITICAL",
                "message": f"Found forbidden {dash_type}. Use standard ASCII hyphen '-' or ':' instead.",
                "snippet": line[:100].strip(),
            })

        # 2. Emoji invariant
        emoji_match = EMOJI_PATTERN.search(line)
        if emoji_match:
            violations.append({
                "file": filename,
                "line": idx,
                "rule": "no-emojis",
                "severity": "CRITICAL",
                "message": f"Found forbidden emoji/symbol '{emoji_match.group()}'. Output must be clean text without emojis.",
                "snippet": line[:100].strip(),
            })

        # 3. Deppenbindestrich invariant (skip negative rule documentation examples like "never 'Abteilungs-Kontingent'")
        for deppen_match in DEPPENBINDESTRICH_PATTERN.finditer(line):
            compound = deppen_match.group()
            prefix = line[max(0, deppen_match.start() - 12):deppen_match.start()].lower()
            if "never '" not in prefix and 'never "' not in prefix:
                corrected = compound.replace("-", "")
                violations.append({
                    "file": filename,
                    "line": idx,
                    "rule": "no-deppenbindestrich",
                    "severity": "HIGH",
                    "message": f"Incorrect German compound hyphenation '{compound}'. Write joined as '{corrected}'.",
                    "snippet": line[:100].strip(),
                })
                break

        # 4. Secret leak checks
        for secret_name, pat in SECRET_PATTERNS:
            if pat.search(line):
                violations.append({
                    "file": filename,
                    "line": idx,
                    "rule": "secret-leak-detection",
                    "severity": "CRITICAL",
                    "message": f"Potential credential leak detected: {secret_name}.",
                    "snippet": pat.sub("[REDACTED]", line[:100]).strip(),
                })

        # 5. Keep a Changelog 1.1.0 invariant for CHANGELOG.md
        if Path(filename).name.lower() == "changelog.md":
            stripped = line.strip()
            if stripped.startswith("### "):
                if not re.match(r"^### (Added|Changed|Deprecated|Removed|Fixed|Security)$", stripped):
                    violations.append({
                        "file": filename,
                        "line": idx,
                        "rule": "keep-a-changelog",
                        "severity": "CRITICAL",
                        "message": (
                            f"Invalid Keep a Changelog section '{stripped}'. "
                            "Only '### Added', '### Changed', '### Deprecated', '### Removed', '### Fixed', or '### Security' are allowed (https://keepachangelog.com/en/1.1.0/)."
                        ),
                        "snippet": stripped[:100],
                    })
            elif stripped.startswith("## "):
                m_ver = re.match(r"^## \[(Unreleased|\d+\.\d+\.\d+(?:-[0-9A-Za-z.\-]+)?(?:\+[0-9A-Za-z.\-]+)?)\](?: - \d{4}-\d{2}-\d{2})?$", stripped)
                if not m_ver:
                    violations.append({
                        "file": filename,
                        "line": idx,
                        "rule": "keep-a-changelog",
                        "severity": "CRITICAL",
                        "message": (
                            f"Invalid Keep a Changelog version header '{stripped}'. "
                            "Use '## [X.Y.Z] - YYYY-MM-DD' or '## [Unreleased]' (https://keepachangelog.com/en/1.1.0/)."
                        ),
                        "snippet": stripped[:100],
                    })
                else:
                    ver_key = m_ver.group(1)
                    if ver_key in seen_changelog_versions:
                        violations.append({
                            "file": filename,
                            "line": idx,
                            "rule": "keep-a-changelog",
                            "severity": "CRITICAL",
                            "message": (
                                f"Duplicate Keep a Changelog version header '[{ver_key}]'. "
                                "Each release version must appear strictly once in CHANGELOG.md."
                            ),
                            "snippet": stripped[:100],
                        })
                    seen_changelog_versions.add(ver_key)

    return violations


def _is_test_file_path(file_path: Path) -> bool:
    """Returns True if file_path is a unit test file or inside a test directory."""
    try:
        name_low = file_path.name.lower()
        if name_low.startswith("test_") or name_low.endswith(("_test.py", "_test.dart", ".test.ts", ".test.js", ".spec.ts", ".spec.js")):
            return True
        tail_parts = [p.lower() for p in file_path.parts[-3:]]
        return "tests" in tail_parts
    except Exception:
        return False


def _is_scratch_file_path(file_path: Path) -> bool:
    """Returns True if file_path is a temporary scratch script inside a scratch/ directory."""
    try:
        parts_low = [p.lower() for p in file_path.parts]
        if "scratch" in parts_low[-3:]:
            return True
        norm_str = str(file_path).lower().replace("/", "\\")
        if "\\antigravity\\brain\\" in norm_str and "\\scratch\\" in norm_str:
            return True
        return False
    except Exception:
        return False


def fix_text(text: str) -> Tuple[str, int]:
    """
    Auto-remediates guardrail violations automatically (zero friction):
    - Converts em-dashes and en-dashes to standard ASCII hyphens.
    - Strips emojis and decorative symbols.
    - Resolves German compound Deppenbindestriche (preserving quoted negative rule examples).
    Returns (cleaned_text, total_fixes_applied).
    """
    fixes = 0

    # 1. Replace dashes
    if EM_DASH in text or EN_DASH in text:
        orig = text
        text = text.replace(EM_DASH, "-").replace(EN_DASH, "-")
        fixes += (orig.count(EM_DASH) + orig.count(EN_DASH))

    # 2. Strip emojis
    emojis = EMOJI_PATTERN.findall(text)
    if emojis:
        fixes += len(emojis)
        text = EMOJI_PATTERN.sub("", text)

    # 3. Fix Deppenbindestriche line-by-line (skipping negative rule examples like "never 'Abteilungs-Kontingent'")
    out_lines = []
    for line in text.splitlines(keepends=True):
        def _repl_deppen(m, current_line=line):
            nonlocal fixes
            compound = m.group()
            prefix = current_line[max(0, m.start() - 12):m.start()].lower()
            if "never '" in prefix or 'never "' in prefix:
                return compound
            fixes += 1
            parts = compound.split("-", 1)
            if len(parts) == 2:
                return parts[0] + parts[1].lower()
            return compound.replace("-", "")

        out_lines.append(DEPPENBINDESTRICH_PATTERN.sub(_repl_deppen, line))
    text = "".join(out_lines)

    return text, fixes


def fix_file(file_path: Path) -> int:
    """Auto-fixes formatting and invariant violations in a file in-place."""
    if file_path.suffix.lower() in SKIP_EXTENSIONS or _is_test_file_path(file_path):
        return 0
    try:
        content = file_path.read_text(encoding="utf-8")
        cleaned, fixes = fix_text(content)
        if fixes > 0:
            file_path.write_text(cleaned, encoding="utf-8")
        return fixes
    except Exception:
        return 0


def check_file(file_path: Path) -> List[Dict[str, Any]]:
    """Inspects a single file for guardrail violations."""
    if file_path.suffix.lower() in SKIP_EXTENSIONS:
        return []
    if _is_test_file_path(file_path):
        return []
    try:
        content = file_path.read_text(encoding="utf-8", errors="replace")
        violations = check_text(content, filename=file_path.name)
        if file_path.name.lower() == "changelog.md" and "keepachangelog.com" not in content.lower():
            violations.append({
                "file": file_path.name,
                "line": 1,
                "rule": "keep-a-changelog",
                "severity": "CRITICAL",
                "message": "CHANGELOG.md must reference https://keepachangelog.com/en/1.1.0/ and https://semver.org/ in its header.",
                "snippet": content.splitlines()[0][:100] if content.splitlines() else "",
            })
        return violations
    except Exception as e:
        return [{
            "file": file_path.name,
            "line": 0,
            "rule": "file-read-error",
            "severity": "LOW",
            "message": f"Could not read file: {e}",
            "snippet": "",
        }]


def check_workspace(root_path: Optional[Path] = None, staged_only: bool = False, strict: bool = False, auto_fix: bool = False) -> Dict[str, Any]:
    """
    Inspects all workspace files (or git staged files) against guardrails.
    In advisory mode (strict=False), provides helpful hints without blocking execution.
    If auto_fix=True, resolves formatting violations automatically.
    """
    target_root = (root_path or Path.cwd()).resolve()
    all_violations = []
    files_checked = 0
    total_fixes = 0

    if staged_only:
        try:
            res = subprocess.run(
                ["git", "diff", "--cached", "--name-only"],
                cwd=target_root,
                capture_output=True,
                text=True,
                check=False
            )
            staged_files = [f.strip() for f in res.stdout.splitlines() if f.strip()]
            for rel_file in staged_files:
                fpath = target_root / rel_file
                if fpath.exists() and fpath.is_file():
                    files_checked += 1
                    if auto_fix:
                        total_fixes += fix_file(fpath)
                    all_violations.extend(check_file(fpath))
        except Exception as e:
            all_violations.append({
                "file": "git",
                "line": 0,
                "rule": "git-staged-error",
                "severity": "HIGH",
                "message": f"Failed to check git staged files: {e}",
                "snippet": "",
            })
    else:
        for dirpath, dirnames, filenames in os.walk(target_root):
            dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and not d.startswith(".")]
            for fname in filenames:
                fpath = Path(dirpath) / fname
                if fpath.suffix.lower() not in SKIP_EXTENSIONS:
                    files_checked += 1
                    if auto_fix:
                        total_fixes += fix_file(fpath)
                    all_violations.extend(check_file(fpath))

    passed = len(all_violations) == 0
    return {
        "passed": passed,
        "target_root": str(target_root),
        "staged_only": staged_only,
        "strict": strict,
        "auto_fix": auto_fix,
        "total_fixes": total_fixes,
        "total_files_checked": files_checked,
        "violations_count": len(all_violations),
        "violations": all_violations,
    }


def verify_task(
    task_id: int,
    test_cmd: Optional[str] = None,
    project_root: Optional[Path] = None,
    strict: bool = False,
    auto_fix: bool = True
) -> Dict[str, Any]:
    """
    Evaluator-Optimizer gate: Validates a task against deterministic guardrails and test commands.
    Designed with zero developer friction:
    - In standard mode (strict=False), guardrails automatically auto-fix formatting or warn without blocking.
    - Transitions task to 'completed' with verified telemetry audit.
    """
    pass

    root = project_root or find_project_root()
    db_path = get_project_db_path(root)
    if not db_path.exists():
        return {
            "verified": False,
            "task_id": task_id,
            "reason": f"Project memory not initialized at {db_path}",
        }

    conn = get_project_connection(root)
    try:
        cursor = conn.cursor()
        cursor.execute("SELECT id, title, description, status, priority FROM project_tasks WHERE id = ?;", (task_id,))
        task = cursor.fetchone()
    finally:
        conn.close()
    if not task:
        return {
            "verified": False,
            "task_id": task_id,
            "reason": f"Task #{task_id} not found on project task board.",
        }

    now_iso = datetime.now(timezone.utc).isoformat()
    verification_details = []

    # 1. Guardrail Check & Optional Auto-Fix (non-blocking unless strict=True)
    guard_res = check_workspace(root_path=root, staged_only=False, auto_fix=auto_fix)
    if guard_res["total_fixes"] > 0:
        verification_details.append(f"Auto-fixed {guard_res['total_fixes']} formatting issues")

    if not guard_res["passed"]:
        if strict:
            return {
                "verified": False,
                "task_id": task_id,
                "reason": f"Strict guardrail check blocked completion with {guard_res['violations_count']} policy violations.",
                "violations": guard_res["violations"][:5],
            }
        else:
            verification_details.append(f"Guardrails advisory: {guard_res['violations_count']} warnings noted (non-blocking)")
    else:
        verification_details.append(f"Guardrails clean ({guard_res['total_files_checked']} files verified)")

    # 2. Test Command Execution Check
    if test_cmd:
        try:
            test_proc = subprocess.run(
                test_cmd,
                shell=True,
                cwd=root,
                capture_output=True,
                text=True,
                timeout=120
            )
            if test_proc.returncode != 0:
                err_snippet = (test_proc.stderr or test_proc.stdout)[:300].strip()
                return {
                    "verified": False,
                    "task_id": task_id,
                    "reason": f"Test command failed with exit code {test_proc.returncode}.",
                    "snippet": err_snippet,
                }
            verification_details.append(f"Test command passed: '{test_cmd}' (exit 0)")
        except Exception as e:
            return {
                "verified": False,
                "task_id": task_id,
                "reason": f"Test command execution error: {e}",
            }

    # 3. Successful Verification Gate Passed: Update Task State
    details_str = "; ".join(verification_details) if verification_details else "Verified successfully"
    conn = get_project_connection(root)
    try:
        cursor = conn.cursor()
        cursor.execute("""
        UPDATE project_tasks
        SET status = 'completed', updated_at = ?
        WHERE id = ?;
        """, (now_iso, task_id))
        cursor.execute(
            "DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;",
            (f"Task #{task_id}:%",),
        )
        cursor.execute(
            "INSERT INTO project_memory_fts (source_table, title_or_key, content) VALUES ('task', ?, ?);",
            (f"Task #{task_id}: {task['title']}", f"completed {task['priority']} {task['description'] or ''}"),
        )
        cursor.execute("""
        INSERT INTO task_verifications (task_id, verifier_type, passed, details, created_at)
        VALUES (?, 'evaluator_optimizer', 1, ?, ?);
        """, (task_id, details_str, now_iso))
        conn.commit()
    finally:
        conn.close()

    return {
        "verified": True,
        "task_id": task_id,
        "task_title": task["title"],
        "status": "completed",
        "details": details_str,
    }


