def handle_tool_call(name: str, args: Dict[str, Any]) -> str:
    """Executes an MCP tool call and returns text content."""
    if not isinstance(args, dict):
        args = {}
    conn = get_connection(DB_PATH)
    try:
        init_db(conn)
        if name in ("skillsdb_get_rules", "skillsdb_rules"):
            cursor = conn.cursor()
            cursor.execute("SELECT key, name, content FROM rules WHERE is_active = 1 ORDER BY key;")
            rows = cursor.fetchall()
            lines = ["# Active Global Rules from Central Database:"]
            for r in rows:
                lines.append(f"\n## Rule: {r['name']} ({r['key']})\n{r['content']}")
            return "\n".join(lines)

        elif name in ("skillsdb_suggest_skills", "skillsdb_suggest"):
            task = args.get("task", "")
            cwd_str = args.get("cwd")
            cwd_p = Path(cwd_str) if cwd_str else None
            # Capture output in memory
            import io
            from contextlib import redirect_stdout
            f = io.StringIO()
            with redirect_stdout(f):
                suggest_skills(conn, task, cwd_path=cwd_p)
            return f.getvalue()

        elif name == "skillsdb_get_skill":
            sname = args.get("name", "")
            sec = args.get("section")
            summ = args.get("summary", False)
            import io
            from contextlib import redirect_stdout
            f = io.StringIO()
            with redirect_stdout(f):
                get_skill(conn, sname, summary=summ, section=sec)
            return f.getvalue()

        elif name in ("skillsdb_guardrail_check", "skillsdb_guardrail"):
            text = args.get("text", "")
            auto_fix = args.get("auto_fix", False)
            violations = check_text(text)
            if auto_fix:
                cleaned, count = fix_text(text)
                return json.dumps({
                    "passed": len(violations) == 0,
                    "violations": violations,
                    "auto_fixed": True,
                    "fix_count": count,
                    "cleaned_text": cleaned
                }, indent=2)
            return json.dumps({
                "passed": len(violations) == 0,
                "violations_count": len(violations),
                "violations": violations
            }, indent=2)

        elif name == "skillsdb_fim_slice":
            raw_fpath = str(args.get("file_path") or args.get("file") or args.get("path") or "").strip()
            if not raw_fpath:
                return "Error: Specify 'file_path' (or 'file' / 'path') to slice."
            fpath = Path(raw_fpath)
            line_num = args.get("line")
            sym = args.get("symbol")
            try:
                if sym:
                    res = slice_fim_symbol(fpath, sym)
                elif line_num is not None:
                    res = slice_fim(fpath, int(line_num))
                else:
                    return "Error: Specify either 'line' or 'symbol' to slice."
                return format_fim_block(res)
            except (FileNotFoundError, ValueError, OSError) as exc:
                return f"Error: {exc}"

        elif name == "skillsdb_agent_template":
            aid = args.get("agent_id") or args.get("id")
            if args.get("list_all") or not aid:
                tmpls = list_agent_templates(conn)
                lines = ["=== AVAILABLE AGENT TEMPLATES ==="]
                for t in tmpls:
                    lines.append(f"  * [{t['id']}] {t['name']}: {t['role']}")
                return "\n".join(lines)
            tmpl = get_agent_template(conn, aid)
            if not tmpl:
                return f"Error: Agent template '{aid}' not found."
            return format_agent_prompt(tmpl)

        elif name == "skillsdb_gitea_status":
            import io
            from contextlib import redirect_stdout
            f = io.StringIO()
            with redirect_stdout(f):
                gitea_status_summary()
            return f.getvalue()

        elif name == "skillsdb_gitea_sync":
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd") or "."
            proj_path = Path(proj_raw)
            msg = args.get("message", "Synchronize workspace via MCP")
            res = save_code_commit(proj_path, message=msg, push=True)
            return json.dumps(res, indent=2)

        elif name == "skillsdb_quota_status":
            return json.dumps(compute_routing_decision(), indent=2)

        elif name == "skillsdb_gemini_digest":
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd")
            proj_p = Path(proj_raw) if proj_raw else None
            res = execute_gemini_digest(
                files=args.get("files") or [],
                query=args.get("query") or "Summarize key findings and line numbers.",
                execution_tier=args.get("tier") or "auto",
                preferred_pool=args.get("pool") or "auto",
                include_git_diff=bool(args.get("git_diff", False)),
                save_fact_key=args.get("save_fact_key") or args.get("save_fact"),
                project_root=proj_p,
            )
            return json.dumps(res, indent=2)

        elif name == "skillsdb_ast_map":
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd")
            proj_p = Path(proj_raw) if proj_raw else None
            sym_filter = args.get("symbol_filter") or args.get("filter") or args.get("query")
            res = execute_ast_map(
                files=args.get("files") or [],
                symbol_filter=sym_filter,
                include_private=bool(args.get("include_private", True)),
                save_fact_key=args.get("save_fact_key") or args.get("save_fact"),
                project_root=proj_p,
            )
            return json.dumps(res, indent=2)

        elif name in ("skillsdb_context", "skillsdb_mem_context"):
            import io
            from contextlib import redirect_stdout
            pass
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd")
            proj_p = Path(proj_raw) if proj_raw else find_project_root()
            pconn = get_project_connection(proj_p)
            try:
                f = io.StringIO()
                with redirect_stdout(f):
                    mem_get_context(pconn, project_root=proj_p)
                return f.getvalue()
            finally:
                pconn.close()

        elif name == "skillsdb_task_board":
            import io
            from contextlib import redirect_stdout
            pass
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd")
            proj_p = Path(proj_raw) if proj_raw else find_project_root()
            action = (args.get("action") or "list").strip().lower()
            tid = args.get("task_id") if args.get("task_id") is not None else args.get("id")
            desc_val = args.get("description") or args.get("desc") or ""
            pconn = get_project_connection(proj_p)
            try:
                f = io.StringIO()
                with redirect_stdout(f):
                    if action == "add" and args.get("title"):
                        mem_task_add(
                            pconn,
                            args["title"],
                            description=desc_val,
                            priority=args.get("priority", "med"),
                            status=args.get("status", "pending"),
                        )
                    elif action == "update" and tid is not None:
                        mem_task_update(
                            pconn,
                            int(tid),
                            status=args.get("status"),
                            priority=args.get("priority"),
                            title=args.get("title"),
                            description=desc_val if ("description" in args or "desc" in args) else None,
                        )
                    else:
                        mem_task_list(pconn, status=args.get("status"), as_json=True)
                return f.getvalue()
            finally:
                pconn.close()

        elif name == "skillsdb_gemini_handover":
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd")
            proj_p = Path(proj_raw) if proj_raw else None
            res = create_web_handover(
                topic=args.get("topic") or "Architectural research",
                files=args.get("files"),
                project_root=proj_p,
                copy_clipboard=bool(args.get("copy_clipboard", True)),
            )
            return json.dumps(res, indent=2)

        elif name == "skillsdb_gemini_ingest":
            proj_raw = args.get("project_path") or args.get("project") or args.get("cwd")
            proj_p = Path(proj_raw) if proj_raw else None
            res = ingest_web_response(
                raw_text=args.get("text"),
                fact_key=args.get("fact_key") or "gemini_web_research_finding",
                project_root=proj_p,
            )
            return json.dumps(res, indent=2)

        return f"Unknown tool: {name}"
    finally:
        conn.close()


def run_mcp_server():
    """Main stdio JSON-RPC 2.0 loop for Model Context Protocol."""
    sys.stderr.write(f"[{SERVER_NAME}] Starting SkillsDB native MCP server (v{__version__})...\n")
    sys.stderr.flush()

    while True:
        req_id = None
        try:
            line = sys.stdin.readline()
            if not line:
                break
            line = line.strip()
            if not line:
                continue

            req = json.loads(line)
            if not isinstance(req, dict):
                continue
            req_id = req.get("id")
            method = req.get("method")
            params = req.get("params") or {}
            if not isinstance(params, dict):
                params = {}

            # Notification handling (no response)
            if req_id is None:
                continue

            if method == "initialize":
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "protocolVersion": "2024-11-05",
                        "capabilities": {
                            "tools": {}
                        },
                        "serverInfo": {
                            "name": SERVER_NAME,
                            "version": __version__
                        }
                    }
                }
            elif method == "ping":
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {}
                }
            elif method == "tools/list":
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "tools": TOOLS_REGISTRY
                    }
                }
            elif method == "resources/list":
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "resources": []
                    }
                }
            elif method == "prompts/list":
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "prompts": []
                    }
                }
            elif method == "tools/call":
                tool_name = params.get("name", "")
                tool_args = params.get("arguments") or params.get("args") or {}
                result_text = handle_tool_call(tool_name, tool_args)
                is_err = isinstance(result_text, str) and (
                    result_text.startswith("Error:") or result_text.startswith("Unknown tool:")
                )
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "content": [
                            {
                                "type": "text",
                                "text": result_text
                            }
                        ],
                        "isError": is_err,
                    }
                }
            else:
                resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "error": {
                        "code": -32601,
                        "message": f"Method not found: {method}"
                    }
                }

            out_line = json.dumps(resp) + "\n"
            sys.stdout.write(out_line)
            sys.stdout.flush()

        except Exception as e:
            sys.stderr.write(f"[{SERVER_NAME}] Error: {e}\n")
            sys.stderr.flush()
            if req_id is not None:
                err_resp = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "error": {
                        "code": -32603,
                        "message": str(e),
                    },
                }
                sys.stdout.write(json.dumps(err_resp) + "\n")
                sys.stdout.flush()


