# SECTION: skillsdb.memory.gitea_service
# =====================================================================
def check_gitea_health(timeout: float = 3.0, db_path: Path = DB_PATH) -> Tuple[bool, Dict[str, Any]]:
    """Checks whether the Gitea service is online and returns version info."""
    config = get_gitea_config(db_path=db_path)
    version_url = f"{config['url']}/api/v1/version"
    headers = {"User-Agent": "SkillsDB-GiteaSync/1.0"}
    if config.get("token"):
        headers["Authorization"] = f"token {config['token']}"
    req = urllib.request.Request(
        version_url,
        headers=headers,
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            if resp.status == 200:
                data = json.loads(resp.read().decode("utf-8"))
                return True, data
    except Exception as e:
        if hasattr(e, "close"):
            try:
                e.close()
            except Exception:
                pass
        healthz_url = f"{config['url']}/api/healthz"
        try:
            h_req = urllib.request.Request(healthz_url, headers={"User-Agent": "SkillsDB-GiteaSync/1.0"})
            with urllib.request.urlopen(h_req, timeout=timeout) as h_resp:
                if h_resp.status == 200:
                    h_data = json.loads(h_resp.read().decode("utf-8"))
                    if h_data.get("status") == "pass":
                        return True, {"version": h_data.get("description", "online"), "status": "pass"}
        except Exception as he:
            if hasattr(he, "close"):
                try:
                    he.close()
                except Exception:
                    pass
        return False, {"error": str(e)}
    return False, {"error": "Unknown status"}


def get_gitea_service_status(db_path: Path = DB_PATH) -> str:
    """Checks service state for Gitea across Windows (sc.exe), Linux (systemd/pgrep), and macOS (launchctl/pgrep)."""
    config = get_gitea_config(db_path=db_path)
    svc_name = config["service_name"]
    if os.name == "nt":
        try:
            proc = subprocess.run(
                ["sc.exe", "query", svc_name],
                capture_output=True,
                text=True,
                encoding="utf-8",
                errors="replace",
                timeout=5,
            )
            for line in proc.stdout.splitlines():
                if "STATE" in line:
                    parts = line.strip().split()
                    if len(parts) >= 4:
                        return parts[3]  # e.g., RUNNING, STOPPED
                    return line.strip()
            return "NOT_FOUND" if proc.returncode != 0 else "UNKNOWN"
        except Exception:
            return "UNKNOWN"

    try:
        if sys.platform.startswith("linux") and shutil.which("systemctl"):
            for cmd in (
                ["systemctl", "--user", "is-active", svc_name],
                ["systemctl", "is-active", svc_name],
            ):
                proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3)
                state = proc.stdout.strip().lower()
                if state == "active":
                    return "RUNNING"
                if state in ("activating", "reloading"):
                    return "START_PENDING"
                if state in ("inactive", "failed", "deactivating"):
                    user_unit = Path.home() / ".config" / "systemd" / "user" / f"{svc_name}.service"
                    sys_unit = Path(f"/etc/systemd/system/{svc_name}.service")
                    if user_unit.exists() or sys_unit.exists():
                        return "STOPPED"
        if sys.platform == "darwin" and shutil.which("launchctl"):
            plist = Path.home() / "Library" / "LaunchAgents" / "dev.local.antigraviton.gitea.plist"
            lproc = subprocess.run(["launchctl", "list"], capture_output=True, text=True, timeout=3)
            if lproc.returncode == 0 and "dev.local.antigraviton.gitea" in lproc.stdout:
                return "RUNNING"
            if plist.exists():
                return "STOPPED"
        if shutil.which("pgrep"):
            pg = subprocess.run(["pgrep", "-f", "gitea.*web"], capture_output=True, text=True, timeout=3)
            if pg.returncode == 0 and pg.stdout.strip():
                return "RUNNING"
        return "NOT_FOUND"
    except Exception:
        return "UNKNOWN"


def inspect_remote_repository(repo_name: str, db_path: Path = DB_PATH) -> Dict[str, Any]:
    """Checks whether a repository with repo_name already exists on Gitea and returns its metadata."""
    config = get_gitea_config(db_path=db_path)
    token = config["token"]
    user = config["user"]
    base_url = config["url"]
    default_html = f"{base_url}/{user}/{repo_name}" if user else base_url
    result = {
        "exists": False,
        "empty": True,
        "name": repo_name,
        "full_name": f"{user}/{repo_name}" if user else repo_name,
        "html_url": default_html,
        "clone_url": None,
        "updated_at": None,
    }
    if not token or not user:
        return result

    quoted_user = urllib.parse.quote(user, safe="")
    quoted_repo = urllib.parse.quote(repo_name, safe="")
    repo_url = f"{base_url}/api/v1/repos/{quoted_user}/{quoted_repo}"
    req = urllib.request.Request(
        repo_url,
        headers={
            "Authorization": f"token {token}",
            "User-Agent": "SkillsDB-GiteaSync/1.0",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=5.0) as resp:
            if resp.status == 200:
                data = json.loads(resp.read().decode("utf-8"))
                result["exists"] = True
                result["empty"] = bool(data.get("empty", False))
                result["full_name"] = data.get("full_name") or result["full_name"]
                result["html_url"] = data.get("html_url") or default_html
                result["clone_url"] = _strip_credentials_from_url(data.get("clone_url"))
                result["updated_at"] = data.get("updated_at")
    except Exception as e:
        if hasattr(e, "close"):
            try:
                e.close()
            except Exception:
                pass
    return result


def ensure_remote_repository(repo_name: str, description: Optional[str] = None) -> Optional[str]:
    """Ensures repository exists in Gitea; creates it if missing and returns a clean, credential-free clone URL."""
    config = get_gitea_config()
    token = config["token"]
    user = config["user"]
    base_url = config["url"]

    if not token or not user:
        return None

    info = inspect_remote_repository(repo_name)
    if info.get("exists") and info.get("clone_url"):
        return _strip_credentials_from_url(info["clone_url"])

    create_urls = []
    if user and user.lower() != "antigravity":
        create_urls.append(f"{base_url}/api/v1/admin/users/{user}/repos")
    create_urls.append(f"{base_url}/api/v1/user/repos")
    payload = json.dumps({
        "name": repo_name,
        "description": description or f"Antigravity workspace {repo_name}",
        "private": True,
        "auto_init": False,
        "default_branch": "main",
    }).encode("utf-8")

    for c_url in create_urls:
        create_req = urllib.request.Request(
            c_url,
            data=payload,
            headers={
                "Authorization": f"token {token}",
                "Content-Type": "application/json",
                "User-Agent": "SkillsDB-GiteaSync/1.0",
            },
        )
        try:
            with urllib.request.urlopen(create_req, timeout=5.0) as resp:
                if resp.status in (200, 201):
                    data = json.loads(resp.read().decode("utf-8"))
                    return _strip_credentials_from_url(data.get("clone_url"))
        except Exception as e:
            if hasattr(e, "close"):
                try:
                    e.close()
                except Exception:
                    pass
            continue
    return None


def delete_remote_repository(repo_name: str, owner: Optional[str] = None, db_path: Path = DB_PATH) -> bool:
    """Deletes a repository in Gitea via API (primarily used for cleaning up temporary test repositories)."""
    config = get_gitea_config(db_path=db_path)
    token = config["token"]
    target_owner = owner or config["user"]
    base_url = config["url"]
    if not token or not target_owner:
        return False

    quoted_owner = urllib.parse.quote(target_owner, safe="")
    quoted_repo = urllib.parse.quote(repo_name, safe="")
    del_url = f"{base_url}/api/v1/repos/{quoted_owner}/{quoted_repo}"
    req = urllib.request.Request(
        del_url,
        method="DELETE",
        headers={
            "Authorization": f"token {token}",
            "User-Agent": "SkillsDB-GiteaSync/1.0",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=5.0) as resp:
            return resp.status in (200, 204)
    except Exception as e:
        if hasattr(e, "close"):
            try:
                e.close()
            except Exception:
                pass
        return False


def list_gitea_repositories() -> List[Dict[str, Any]]:
    """Retrieves all repositories owned by the configured Gitea user."""
    config = get_gitea_config()
    target_user = config.get("user")
    token = config.get("token")
    if not token:
        return []

    urls = []
    if target_user:
        urls.append(f"{config['url']}/api/v1/users/{target_user}/repos?limit=100")
    urls.append(f"{config['url']}/api/v1/user/repos?limit=100")

    for url in urls:
        req = urllib.request.Request(
            url,
            headers={
                "Authorization": f"token {token}",
                "User-Agent": "SkillsDB-GiteaSync/1.0",
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=5.0) as resp:
                if resp.status == 200:
                    repos = json.loads(resp.read().decode("utf-8"))
                    if repos:
                        return repos
        except Exception as e:
            if hasattr(e, "close"):
                try:
                    e.close()
                except Exception:
                    pass
            continue
    return []


# =====================================================================
# SECTION: skillsdb.memory.gitea_releases
# =====================================================================
def parse_keep_a_changelog(changelog_path: Path) -> List[Dict[str, str]]:
    """
    Parses a CHANGELOG.md formatted according to Keep a Changelog 1.1.0 (https://keepachangelog.com/en/1.1.0/).
    Returns a list of dicts (newest first): [{'version': '1.0.6', 'tag': 'v1.0.6', 'date': '2026-10-19', 'body': '...'}].
    """
    changelog_path = Path(changelog_path)
    if not changelog_path.exists():
        return []
    try:
        lines = changelog_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except Exception:
        return []

    entries: List[Dict[str, str]] = []
    current_ver: Optional[str] = None
    current_date: str = ""
    current_lines: List[str] = []

    ver_re = re.compile(r"^## \[[vV]?(\d+\.\d+\.\d+(?:-[0-9A-Za-z.\-]+)?)\](?: - (\d{4}-\d{2}-\d{2}))?\s*$")
    link_ref_re = re.compile(r"^\[[^\]]+\]:\s*https?://")

    def _flush():
        if current_ver and current_lines:
            body_text = "\n".join(current_lines).strip()
            footer = "\n\n---\n*Format based on [Keep a Changelog](https://keepachangelog.com/en/1.1.0/) and [Semantic Versioning](https://semver.org/spec/v2.0.0.html).*"
            if "keepachangelog.com" not in body_text:
                body_text += footer
            entries.append({
                "version": current_ver,
                "tag": f"v{current_ver}",
                "date": current_date,
                "body": body_text,
            })

    for line in lines:
        if line.startswith("## "):
            _flush()
            m = ver_re.match(line.strip())
            if m:
                current_ver = m.group(1)
                current_date = m.group(2) or ""
                current_lines = [line.strip()]
            else:
                current_ver = None
                current_date = ""
                current_lines = []
        elif current_ver is not None:
            if link_ref_re.match(line.strip()):
                continue
            current_lines.append(line)

    _flush()
    return entries


def _extract_changelog_section(
    project_root: Path,
    target_version: Optional[str] = None,
) -> Tuple[Optional[str], Optional[str], Optional[str]]:
    """
    Reads VERSION and CHANGELOG.md in project_root and extracts:
    (normalized_tag, release_title, markdown_body).
    """
    raw_ver = target_version.strip() if target_version else None
    if not raw_ver:
        ver_file = project_root / "VERSION"
        if ver_file.exists():
            try:
                v_txt = ver_file.read_text(encoding="utf-8-sig", errors="ignore").strip()
                if v_txt and len(v_txt) <= 32:
                    raw_ver = v_txt
            except Exception:
                pass

    changelog_file = project_root / "CHANGELOG.md"
    entries = parse_keep_a_changelog(changelog_file) if changelog_file.exists() else []
    clean_target = raw_ver.lstrip("vV") if raw_ver else None

    for entry in entries:
        if clean_target is None or entry["version"] == clean_target:
            tag_name = entry["tag"]
            title = f"{project_root.name} {tag_name}"
            return tag_name, title, entry["body"]

    if not raw_ver:
        return None, None, None

    tag_name = raw_ver if raw_ver.startswith("v") else f"v{raw_ver}"
    title = f"{project_root.name} {tag_name}"
    return tag_name, title, None



def _resolve_github_repo_slug(project_root: Path) -> Optional[str]:
    """Resolves the 'owner/repo' slug from a GitHub remote ('github' or 'origin') if configured."""
    for rem in ("github", "origin"):
        try:
            res = subprocess.run(
                ["git", "remote", "get-url", rem],
                cwd=str(project_root),
                capture_output=True,
                text=True,
                timeout=5,
            )
            if res.returncode == 0 and "github.com" in (res.stdout or "").lower():
                m = re.search(r"github\.com[:/]([^/\s]+/[^/\s]+?)(?:\.git)?\s*$", res.stdout.strip(), re.IGNORECASE)
                if m:
                    return m.group(1)
        except Exception:
            pass
    return None


RELEASE_DELIVERABLE_EXTENSIONS = (
    ".apk", ".aab", ".ipa",
    ".exe", ".msi", ".msix",
    ".dmg", ".pkg", ".deb", ".rpm", ".appimage",
    ".xpi", ".crx", ".vsix",
    ".whl", ".jar", ".nupkg",
    ".zip", ".7z", ".tar.gz",
)

DIRECT_ROOT_ARTIFACT_EXTENSIONS = (
    ".apk", ".aab", ".ipa",
    ".msi", ".msix", ".dmg", ".pkg", ".deb", ".rpm", ".appimage",
    ".xpi", ".crx", ".vsix", ".whl", ".nupkg",
)


def _discover_project_release_artifacts(
    project_root: Path,
    repo_name: str,
    tag: str,
) -> List[Path]:
    """
    Discovers compiled deliverable artifacts belonging to the project (APKs, binaries,
    installers, extension packages, wheels, or release archives in releases/ and dist/).
    Excludes intermediate unsigned/unaligned build files and third-party vendor binaries.
    """
    project_root = Path(project_root)
    clean_ver = tag.lstrip("vV")
    repo_lower = repo_name.lower()
    found: List[Path] = []
    seen: set = set()

    def _is_excluded_name(fname: str) -> bool:
        low = fname.lower()
        if low.endswith(("-unsigned.apk", "-aligned.apk", "-unaligned.apk", ".tmp", ".bak")):
            return True
        if low.startswith(("gitea-", "apktool", "jadx", "uber-apk-signer", "bundletool")) and "gitea" not in repo_lower:
            return True
        return False

    dedicated_dirs = [
        project_root / "releases",
        project_root / "dist",
        project_root / "out",
        project_root / "build" / "outputs" / "apk" / "release",
        project_root / "build" / "outputs" / "bundle" / "release",
    ]
    for sdir in dedicated_dirs:
        if sdir.exists() and sdir.is_dir():
            for p in sorted(sdir.iterdir()):
                if not p.is_file() or _is_excluded_name(p.name):
                    continue
                low_name = p.name.lower()
                if any(low_name.endswith(ext) for ext in RELEASE_DELIVERABLE_EXTENSIONS):
                    rp = p.resolve()
                    if rp not in seen:
                        seen.add(rp)
                        found.append(p)

    if project_root.exists() and project_root.is_dir():
        for p in sorted(project_root.iterdir()):
            if not p.is_file() or _is_excluded_name(p.name):
                continue
            low_name = p.name.lower()
            if any(low_name.endswith(ext) for ext in DIRECT_ROOT_ARTIFACT_EXTENSIONS):
                rp = p.resolve()
                if rp not in seen:
                    seen.add(rp)
                    found.append(p)
            elif low_name.endswith((".exe", ".jar")):
                if (
                    repo_lower in low_name
                    or "clean" in low_name
                    or "signed" in low_name
                    or "release" in low_name
                    or "setup" in low_name
                    or "installer" in low_name
                ):
                    rp = p.resolve()
                    if rp not in seen:
                        seen.add(rp)
                        found.append(p)

    tag_matched = [
        p for p in found
        if (tag.lower() in p.name.lower() or (clean_ver and clean_ver.lower() in p.name.lower()))
    ]
    candidates = tag_matched if tag_matched else found
    candidates.sort(
        key=lambda p: (
            0 if ("clean" in p.name.lower() or "signed" in p.name.lower() or "release" in p.name.lower()) else 1,
            p.name,
        )
    )
    return candidates


def _attach_release_binary_assets(
    base_url: str,
    owner: str,
    repo_name: str,
    rel_id: Any,
    tag: str,
    existing_assets: Any,
    token: str,
    project_root: Path,
    overwrite: bool = False,
) -> List[str]:
    """
    Automatically attaches compiled project deliverable artifacts (*.apk, *.aab, *.exe, *.msi,
    *.xpi, *.whl, etc.) from project_root (or releases/ / dist/ or git tag history)
    as downloadable Gitea Release Assets via POST /api/v1/repos/{owner}/{repo}/releases/{id}/assets.
    """
    uploaded_names: List[str] = []
    if not rel_id or not base_url or not owner or not repo_name or not token:
        return uploaded_names

    project_root = Path(project_root)
    existing_map = {
        a.get("name"): a.get("id")
        for a in (existing_assets or [])
        if isinstance(a, dict) and a.get("name")
    }

    candidates = _discover_project_release_artifacts(project_root, repo_name, tag)
    if not candidates:
        return uploaded_names

    clean_ver = tag.lstrip("vV")
    primary_file = candidates[0]
    ext = ".tar.gz" if primary_file.name.lower().endswith(".tar.gz") else primary_file.suffix
    low_primary = primary_file.name.lower()

    if low_primary.endswith(".apk"):
        asset_name = f"{repo_name}-{tag}-clean-signed.apk" if "clean" in low_primary else f"{repo_name}-{tag}.apk"
        content_type = "application/vnd.android.package-archive"
    else:
        if tag.lower() in low_primary or (clean_ver and clean_ver.lower() in low_primary):
            asset_name = primary_file.name
        else:
            asset_name = f"{repo_name}-{tag}{ext}"
        content_type = "application/zip" if ext in (".zip", ".whl", ".jar", ".xpi") else "application/octet-stream"

    if asset_name in existing_map and not overwrite:
        return uploaded_names

    file_bytes: Optional[bytes] = None
    is_tag_specific_file = tag.lower() in low_primary or (clean_ver and clean_ver.lower() in low_primary)
    if is_tag_specific_file:
        try:
            file_bytes = primary_file.read_bytes()
        except Exception:
            pass

    if not file_bytes and (project_root / ".git" / "HEAD").exists():
        try:
            rel_path = primary_file.relative_to(project_root).as_posix()
            git_show = subprocess.run(
                ["git", "show", f"{tag}:{rel_path}"],
                cwd=str(project_root),
                capture_output=True,
                timeout=15,
            )
            if git_show.returncode == 0 and git_show.stdout:
                file_bytes = git_show.stdout
        except Exception:
            pass

    if not file_bytes:
        try:
            file_bytes = primary_file.read_bytes()
        except Exception:
            return uploaded_names

    try:
        if asset_name in existing_map and existing_map[asset_name]:
            del_req = urllib.request.Request(
                f"{base_url.rstrip('/')}/api/v1/repos/{owner}/{repo_name}/releases/{rel_id}/assets/{existing_map[asset_name]}",
                method="DELETE",
                headers={"Authorization": f"token {token}", "User-Agent": "SkillsDB-GiteaSync/1.0"},
            )
            with urllib.request.urlopen(del_req, timeout=10.0):
                pass
        boundary = f"----SkillsDBAssetBoundary{uuid.uuid4().hex}"
        body = (
            f"--{boundary}\r\n"
            f'Content-Disposition: form-data; name="attachment"; filename="{asset_name}"\r\n'
            f"Content-Type: {content_type}\r\n\r\n"
        ).encode("utf-8") + file_bytes + f"\r\n--{boundary}--\r\n".encode("utf-8")
        up_url = f"{base_url.rstrip('/')}/api/v1/repos/{owner}/{repo_name}/releases/{rel_id}/assets?name={urllib.parse.quote(asset_name)}"
        up_req = urllib.request.Request(
            up_url,
            data=body,
            method="POST",
            headers={
                "Authorization": f"token {token}",
                "Content-Type": f"multipart/form-data; boundary={boundary}",
                "User-Agent": "SkillsDB-GiteaSync/1.0",
            },
        )
        with urllib.request.urlopen(up_req, timeout=30.0) as resp:
            if resp.status in (200, 201):
                uploaded_names.append(asset_name)
    except Exception as e:
        if hasattr(e, "close"):
            try:
                e.close()
            except Exception:
                pass
    return uploaded_names


def sync_changelog_releases(
    project_root: Path,
    sync_github: bool = False,
    overwrite_existing: bool = False,
    db_path: Path = DB_PATH,
    repo_name: Optional[str] = None,
) -> List[str]:
    """
    Synchronizes all version entries from CHANGELOG.md (Keep a Changelog 1.1.0 format)
    as formal Releases on Gitea (and optionally GitHub if a github remote and gh CLI exist).
    Returns the list of synced release tags.
    """
    changelog_path = project_root / "CHANGELOG.md"
    if not changelog_path.exists() or _is_temp_workspace(project_root):
        return []

    entries = parse_keep_a_changelog(changelog_path)
    if not entries:
        return []

    config = get_gitea_config(db_path=db_path)
    token = config.get("token")
    owner = config.get("user")
    base_url = config.get("url")
    resolved_repo_name = repo_name or project_root.name
    git_cfg = project_root / ".git" / "config"
    if not repo_name and git_cfg.exists():
        try:
            raw_cfg = git_cfg.read_text(encoding="utf-8", errors="ignore")
            for m in re.finditer(r"^\s*url\s*=\s*https?://(?:[^@/\s]+@)?([^/\s]+)/([^/\s]+)/([^\s/]+?)(?:\.git)?\s*$", raw_cfg, re.MULTILINE):
                host_port, _, rname = m.groups()
                if "localhost:3000" in host_port or "127.0.0.1:3000" in host_port or (base_url and host_port in base_url):
                    resolved_repo_name = rname
                    break
        except Exception:
            pass
    repo_name = resolved_repo_name
    synced_tags: List[str] = []

    if shutil.which("git") and (project_root / ".git" / "HEAD").exists():
        try:
            tag_res = subprocess.run(
                ["git", "tag"],
                cwd=str(project_root),
                capture_output=True,
                text=True,
                timeout=5,
            )
            local_tags = set(tag_res.stdout.split()) if tag_res.returncode == 0 else set()
            created_tag = False
            latest_tag = entries[0]["tag"]
            if latest_tag not in local_tags:
                subprocess.run(
                    ["git", "-c", "user.name=Antigravity", "-c", "user.email=antigravity@local.dev", "tag", "-a", latest_tag, "-m", f"{repo_name} {latest_tag}"],
                    cwd=str(project_root),
                    capture_output=True,
                    timeout=5,
                )
                created_tag = True
            if created_tag:
                if token and owner:
                    subprocess.run(
                        _get_git_auth_cmd_prefix(db_path=db_path) + ["push", "origin", "--tags"],
                        cwd=str(project_root),
                        capture_output=True,
                        timeout=30,
                    )
                else:
                    synced_tags.append(latest_tag)
        except Exception:
            pass

    latest_tag = entries[0]["tag"]
    gitea_enabled = str(config.get("enabled", "auto")).strip().lower() not in ("false", "0", "no", "off", "disabled")
    if gitea_enabled and token and owner and base_url:
        try:
            existing_map: Dict[str, Dict[str, Any]] = {}
            page = 1
            while page <= 5:
                rel_url = f"{base_url}/api/v1/repos/{owner}/{repo_name}/releases?limit=100&page={page}"
                req = urllib.request.Request(
                    rel_url,
                    headers={
                        "Authorization": f"token {token}",
                        "User-Agent": "SkillsDB-GiteaSync/1.0",
                    },
                )
                with urllib.request.urlopen(req, timeout=5.0) as resp:
                    page_list = json.loads(resp.read().decode("utf-8"))
                if not isinstance(page_list, list) or not page_list:
                    break
                for r in page_list:
                    if isinstance(r, dict) and r.get("tag_name"):
                        existing_map[str(r.get("tag_name"))] = r
                if len(page_list) < 100:
                    break
                page += 1

            for entry in reversed(entries):
                tag = entry["tag"]
                body = entry["body"]
                rel_title = f"{repo_name} {tag}"
                is_prerelease = "-" in entry["version"]
                if tag in existing_map:
                    existing_body = (existing_map[tag].get("body") or "").strip()
                    is_latest = (tag == latest_tag)
                    body_matches = (existing_body == body.strip()) if is_latest else ("keepachangelog.com" in existing_body)
                    if not overwrite_existing and body_matches and bool(existing_map[tag].get("prerelease")) == is_prerelease:
                        if is_latest:
                            _attach_release_binary_assets(base_url, owner, repo_name, existing_map[tag].get("id"), tag, existing_map[tag].get("assets", []), token, project_root)
                        continue
                    rel_id = existing_map[tag]["id"]
                    target_url = f"{base_url}/api/v1/repos/{owner}/{repo_name}/releases/{rel_id}"
                    method = "PATCH"
                else:
                    target_url = f"{base_url}/api/v1/repos/{owner}/{repo_name}/releases"
                    method = "POST"

                target_branch = "main"
                try:
                    br_res = subprocess.run(
                        ["git", "rev-parse", "--abbrev-ref", "HEAD"],
                        cwd=str(project_root),
                        capture_output=True,
                        text=True,
                        timeout=3,
                    )
                    br_name = (br_res.stdout or "").strip()
                    if is_prerelease and br_res.returncode == 0 and br_name and br_name != "HEAD":
                        target_branch = br_name
                except Exception:
                    pass

                payload = json.dumps({
                    "tag_name": tag,
                    "target_commitish": target_branch,
                    "name": rel_title,
                    "body": body,
                    "draft": False,
                    "prerelease": is_prerelease,
                }).encode("utf-8")
                up_req = urllib.request.Request(
                    target_url,
                    data=payload,
                    method=method,
                    headers={
                        "Authorization": f"token {token}",
                        "Content-Type": "application/json",
                        "User-Agent": "SkillsDB-GiteaSync/1.0",
                    },
                )
                with urllib.request.urlopen(up_req, timeout=5.0) as up_resp:
                    if up_resp.status in (200, 201):
                        up_data = json.loads(up_resp.read().decode("utf-8"))
                        _attach_release_binary_assets(base_url, owner, repo_name, up_data.get("id"), tag, up_data.get("assets", []), token, project_root)
                        if tag not in synced_tags:
                            synced_tags.append(tag)
        except Exception as e:
            if hasattr(e, "close"):
                try:
                    e.close()
                except Exception:
                    pass

    if sync_github and shutil.which("gh"):
        try:
            gh_slug = _resolve_github_repo_slug(project_root)
            repo_args = ["--repo", gh_slug] if gh_slug else []
            if gh_slug:
                subprocess.run(
                    ["git", "push", "github", "--tags"],
                    cwd=str(project_root),
                    capture_output=True,
                    timeout=30,
                )

            # Fetch all existing GitHub releases in a single API call instead of N*2 subprocesses
            gh_existing_map: Optional[Dict[str, str]] = None
            if gh_slug:
                api_res = subprocess.run(
                    ["gh", "api", f"repos/{gh_slug}/releases?per_page=100"],
                    cwd=str(project_root),
                    capture_output=True,
                    text=True,
                    timeout=20,
                )
                if api_res.returncode == 0 and (api_res.stdout or "").strip():
                    try:
                        gh_list = json.loads(api_res.stdout)
                        if isinstance(gh_list, list):
                            gh_existing_map = {
                                str(r.get("tag_name")): str(r.get("body") or "")
                                for r in gh_list
                                if isinstance(r, dict) and r.get("tag_name")
                            }
                    except Exception:
                        gh_existing_map = None

            for entry in reversed(entries):
                tag = entry["tag"]
                body = entry["body"]
                rel_title = f"{repo_name} {tag}"
                is_latest = (tag == latest_tag)

                if gh_existing_map is not None:
                    if tag in gh_existing_map:
                        gh_body = gh_existing_map[tag].strip()
                        gh_matches = (gh_body == body.strip()) if is_latest else ("keepachangelog.com" in gh_body)
                        if not overwrite_existing and gh_matches:
                            continue
                        gh_action = "edit"
                    else:
                        gh_action = "create"
                else:
                    if not overwrite_existing and not is_latest:
                        continue
                    chk = subprocess.run(
                        ["gh", "release", "view", tag] + repo_args,
                        cwd=str(project_root),
                        capture_output=True,
                        text=True,
                        timeout=15,
                    )
                    if chk.returncode == 0:
                        if not overwrite_existing and "keepachangelog.com" in (chk.stdout or ""):
                            continue
                        gh_action = "edit"
                    else:
                        gh_action = "create"

                with tempfile.NamedTemporaryFile("w", suffix=".md", delete=False, encoding="utf-8") as tf:
                    tf.write(body)
                    tmp_path = tf.name
                try:
                    prerelease_args = ["--prerelease"] if ("-" in entry["version"]) else []
                    if gh_action == "edit":
                        gh_e = subprocess.run(
                            ["gh", "release", "edit", tag, "--title", rel_title, "--notes-file", tmp_path] + prerelease_args + repo_args,
                            cwd=str(project_root),
                            capture_output=True,
                            timeout=20,
                        )
                        if gh_e.returncode == 0 and tag not in synced_tags:
                            synced_tags.append(tag)
                    else:
                        gh_c = subprocess.run(
                            ["gh", "release", "create", tag, "--title", rel_title, "--notes-file", tmp_path] + prerelease_args + repo_args,
                            cwd=str(project_root),
                            capture_output=True,
                            timeout=20,
                        )
                        if gh_c.returncode == 0 and tag not in synced_tags:
                            synced_tags.append(tag)
                finally:
                    Path(tmp_path).unlink(missing_ok=True)
        except Exception:
            pass

    return synced_tags


# =====================================================================
# SECTION: skillsdb.memory.gitea_sync
# =====================================================================
def flush_all_pending_pushes(db_path: Path = DB_PATH) -> List[str]:
    """
    Scans all organically learned workspaces for unpushed local commits (created while
    Gitea or the fileserver was temporarily offline) and pushes them to Gitea.
    Returns the list of workspace names that were successfully flushed.
    """
    flushed: List[str] = []
    learned = get_learned_workspaces(db_path=db_path, prune_missing=False)
    for name, path_str in sorted(learned.items(), key=lambda x: x[0].lower()):
        try:
            ws_path = Path(path_str)
            if ws_path.exists() and (ws_path / ".git" / "HEAD").exists() and not _is_temp_workspace(ws_path):
                if _has_unpushed_commits(ws_path):
                    if _push_to_origin(ws_path, async_push=False, _allow_retry=False):
                        flushed.append(name)
        except Exception:
            continue
    return flushed


def ensure_gitea_online(
    auto_recover: bool = True,
    flush_pending: bool = False,
    db_path: Path = DB_PATH,
) -> Dict[str, Any]:
    """
    Verifies Gitea service and API health. If the service is STOPPED or the API
    is unreachable, automatically attempts to start the service across Windows (sc.exe),
    Linux (systemd --user), and macOS (launchctl) and optionally flushes pending commits.
    """
    svc_status = get_gitea_service_status(db_path=db_path)
    online, v_info = check_gitea_health(timeout=1.5, db_path=db_path)
    recovered = False
    flushed_repos: List[str] = []

    if auto_recover and (not online or svc_status in ("STOPPED", "STOP_PENDING")):
        config = get_gitea_config(db_path=db_path)
        svc_name = config["service_name"]
        if os.name == "nt":
            try:
                if svc_status in ("STOPPED", "STOP_PENDING") and online:
                    subprocess.run(["taskkill", "/F", "/IM", "gitea.exe"], capture_output=True, timeout=5)
                    time.sleep(0.5)
                start_res = subprocess.run(
                    ["sc.exe", "start", svc_name],
                    capture_output=True,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=8,
                )
                if start_res.returncode == 0 or "1056" in start_res.stdout:
                    for _ in range(6):
                        time.sleep(0.8)
                        online, v_info = check_gitea_health(timeout=1.0, db_path=db_path)
                        if online:
                            recovered = True
                            break
                    svc_status = get_gitea_service_status(db_path=db_path)
            except Exception:
                pass
        else:
            try:
                started = False
                if sys.platform.startswith("linux") and shutil.which("systemctl"):
                    res = subprocess.run(
                        ["systemctl", "--user", "start", svc_name],
                        capture_output=True,
                        text=True,
                        timeout=8,
                    )
                    started = res.returncode == 0
                elif sys.platform == "darwin" and shutil.which("launchctl"):
                    plist = Path.home() / "Library" / "LaunchAgents" / "dev.local.antigraviton.gitea.plist"
                    if plist.exists():
                        res = subprocess.run(["launchctl", "load", "-w", str(plist)], capture_output=True, text=True, timeout=8)
                        started = res.returncode == 0
                if started:
                    for _ in range(6):
                        time.sleep(0.8)
                        online, v_info = check_gitea_health(timeout=1.0, db_path=db_path)
                        if online:
                            recovered = True
                            break
                    svc_status = get_gitea_service_status(db_path=db_path)
            except Exception:
                pass

    if online and (flush_pending or recovered):
        flushed_repos = flush_all_pending_pushes(db_path=db_path)

    return {
        "online": online,
        "service_status": svc_status,
        "recovered": recovered,
        "flushed_repos": flushed_repos,
        "version": v_info.get("version") if online else None,
        "error": None if online else v_info.get("error", "Gitea service unreachable"),
    }


def is_gitea_configured(project_root: Optional[Path] = None, db_path: Path = DB_PATH) -> bool:
    """
    Returns True when Gitea integration is configured and enabled on this machine, or False
    when SkillsDB is running in standalone SkillsDB-only mode (e.g. installed with
    -SkipGiteaService / --skip-gitea-service, disabled via gitea-config --disable, or
    deployed without Gitea credentials/service).
    """
    cfg = get_gitea_config(db_path=db_path)
    enabled_flag = str(cfg.get("enabled", "auto")).strip().lower()
    if enabled_flag in ("false", "0", "no", "off", "disabled"):
        return False
    if enabled_flag in ("true", "1", "yes", "on", "enabled"):
        return True
    if cfg.get("token") or cfg.get("user"):
        return True
    if project_root and _get_configured_gitea_repo_url(Path(project_root)):
        return True
    svc_st = get_gitea_service_status(db_path=db_path)
    return svc_st in ("RUNNING", "START_PENDING")


def gitea_status_summary():
    """Prints comprehensive health and status report for Gitea integration, auto-healing if stopped."""
    config = get_gitea_config()
    if not is_gitea_configured():
        print("=" * 60)
        print("SkillsDB - Gitea Integration Status")
        print("=" * 60)
        print("Operation Mode:   Standalone SkillsDB-Only (Gitea optional / not configured)")
        print("Project Memory:   ACTIVE (.agents/memory.db + local Git commits)")
        print("Enable Gitea:     Run 'skillsdb gitea-config --enable' or 'install-antigraviton.ps1'")
        print("=" * 60)
        return
    health = ensure_gitea_online(auto_recover=True, flush_pending=True)
    svc_status = health["service_status"]
    online = health["online"]
    repos = list_gitea_repositories() if online else []

    print("=" * 60)
    print("SkillsDB - Gitea Integration Status")
    print("=" * 60)
    if health.get("recovered"):
        print("Auto-Recovery:    Service 'gitea' was STOPPED and automatically restarted!")
    if health.get("flushed_repos"):
        print(f"Catch-Up Sync:    Pushed pending commits for: {', '.join(health['flushed_repos'])}")
    print(f"Windows Service:  {config['service_name']} ({svc_status})")
    print(f"Server URL:       {config['url']}")
    print(f"API Health:       {'ONLINE' if online else 'OFFLINE'}")
    if online:
        print(f"Gitea Version:    {health.get('version') or 'unknown'}")
        print(f"Repository Owner: {config['user'] or '(not configured)'}")
        print(f"Tracked Repos:    {len(repos)}")
        for r in sorted(repos, key=lambda x: x.get("name", "").lower()):
            print(f"  * {r.get('full_name')} ({r.get('html_url')})")
    else:
        print(f"Diagnostics:      [CRITICAL] {health.get('error', 'Server unreachable')}")
    print("=" * 60)


def _get_configured_gitea_repo_url(project_root: Path) -> Optional[str]:
    """Inspects .git/config to see if origin or gitea remote points to the local Gitea server and returns its clean browser URL."""
    git_cfg = project_root / ".git" / "config"
    if not git_cfg.exists():
        return None
    try:
        _scrub_workspace_git_config_credentials(project_root)
        raw = git_cfg.read_text(encoding="utf-8", errors="ignore")
        cfg = get_gitea_config()
        base_url = cfg.get("url", "http://localhost:3000").rstrip("/")
        for m in re.finditer(r"^\s*url\s*=\s*(https?://(?:[^@/\s]+@)?([^/\s]+)/([^/\s]+)/([^\s/]+?)(?:\.git)?)\s*$", raw, re.MULTILINE):
            _, host_port, owner, rname = m.groups()
            if "localhost:3000" in host_port or "127.0.0.1:3000" in host_port or host_port in base_url:
                return f"{base_url}/{owner}/{rname}"
    except Exception:
        pass
    return None


def get_workspace_git_telemetry(project_root: Path, flush_pending: bool = False, auto_recover: bool = True) -> Optional[str]:
    """
    Returns a compact Git & Gitea status string (~20 tokens), auto-recovers the Gitea
    service if STOPPED (when auto_recover=True), flushes any pending unpushed commits upon
    recovery or when flush_pending=True, and emits an unmissable alert if Gitea is offline
    or if a repository name collision exists on Gitea.
    """
    if not project_root or not (project_root / ".git" / "HEAD").exists():
        return None
    if not shutil.which("git"):
        return None

    extra_notices: List[str] = []
    gitea_online = False
    gitea_active = is_gitea_configured(project_root)
    if not _is_temp_workspace(project_root) and gitea_active:
        try:
            health = ensure_gitea_online(auto_recover=auto_recover, flush_pending=flush_pending)
            gitea_online = bool(health.get("online"))
            if not gitea_online:
                svc_st = health.get("service_status", "STOPPED")
                extra_notices.append(
                    f"[CRITICAL GITEA ALERT]: Local Gitea server (http://127.0.0.1:3000) is OFFLINE (Service: {svc_st}) and could not be auto-started (fileserver or service unreachable). Commits are saved locally only. YOU MUST IMMEDIATELY WARN THE USER IN YOUR RESPONSE THAT GITEA IS CURRENTLY OFFLINE!"
                )
            else:
                if health.get("recovered"):
                    extra_notices.append(
                        "[GITEA AUTO-RECOVERY]: Service 'gitea' was STOPPED and has been automatically restarted by SkillsDB."
                    )
                if health.get("flushed_repos"):
                    extra_notices.append(
                        f"[GITEA CATCH-UP SYNC]: Automatically pushed pending local commits from offline window for: {', '.join(health['flushed_repos'])}."
                    )
        except Exception:
            pass

    try:
        st_res = subprocess.run(
            ["git", "status", "--porcelain", "--branch"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=1.5,
        )
        if st_res.returncode != 0:
            return "\n".join(extra_notices) if extra_notices else None

        lines = [l for l in st_res.stdout.splitlines() if l.strip()]
        branch_info = "main"
        sync_state = "synced"
        dirty_files = []

        configured_gitea_url = _get_configured_gitea_repo_url(project_root)

        for line in lines:
            if line.startswith("## "):
                header = line[3:].strip()
                if "..." in header:
                    branch_part, rest = header.split("...", 1)
                    branch_info = branch_part.strip()
                    if "[" in rest and "]" in rest:
                        bracket = rest[rest.find("[") + 1 : rest.find("]")]
                        sync_state = f"{bracket} | {configured_gitea_url}" if configured_gitea_url else bracket
                    else:
                        sync_state = f"synced with Gitea: {configured_gitea_url}" if configured_gitea_url else "synced with Gitea"
                else:
                    branch_info = header.split()[0] if header else "main"
                    sync_state = f"Gitea remote: {configured_gitea_url}" if configured_gitea_url else "local only"
            else:
                if len(line) > 3:
                    fpath = line[3:].strip().strip('"')
                    if " -> " in fpath:
                        fpath = fpath.split(" -> ")[-1]
                    dirty_files.append(Path(fpath).name)

        if not _is_temp_workspace(project_root) and gitea_online and not configured_gitea_url:
            rem_info = inspect_remote_repository(project_root.name)
            if rem_info.get("exists"):
                extra_notices.append(
                    f"[GITEA COLLISION ALERT]: Local workspace is not yet linked to Gitea, but a repository named '{rem_info['full_name']}' ALREADY EXISTS on Gitea ({rem_info['html_url']}). Ask the user how to proceed before linking or pushing!"
                )

        rev_res = subprocess.run(
            ["git", "rev-parse", "--short", "HEAD"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=1.0,
        )
        short_hash = rev_res.stdout.strip() if rev_res.returncode == 0 else "unborn"

        if dirty_files:
            preview = ", ".join(dirty_files[:4])
            if len(dirty_files) > 4:
                preview += f" (+{len(dirty_files) - 4} more)"
            tree_str = f"{len(dirty_files)} modified: {preview}"
        else:
            tree_str = "clean"

        base_line = f"Git Telemetry: branch '{branch_info}' @ {short_hash} ({tree_str} | {sync_state})"
        if extra_notices:
            return "\n".join([base_line] + [f"  {n}" for n in extra_notices])
        return base_line
    except Exception:
        return "\n".join(extra_notices) if extra_notices else None


def _ensure_git_safe_directory(project_root: Path):
    """Automatically registers project_root in git global safe.directory if dubious ownership is detected (e.g. exFAT or secondary drives)."""
    chk = subprocess.run(
        ["git", "rev-parse", "--git-dir"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    if chk.returncode != 0 and "dubious ownership" in (chk.stderr or ""):
        posix_path = str(project_root.resolve()).replace("\\", "/")
        subprocess.run(
            ["git", "config", "--global", "--add", "safe.directory", posix_path],
            capture_output=True,
        )


def _clear_readonly_in_git(dot_git: Path):
    """Clears Windows ReadOnly file attributes inside a partial or corrupted .git directory so git init can heal it."""
    import stat
    if not dot_git.exists():
        return
    try:
        for root_dir, dirs, files in os.walk(str(dot_git)):
            for fname in files:
                fpath = os.path.join(root_dir, fname)
                try:
                    os.chmod(fpath, stat.S_IWRITE | stat.S_IREAD)
                except Exception:
                    pass
    except Exception:
        pass


def _get_current_branch(project_root: Path) -> str:
    """Returns the currently checked-out branch name in project_root (fallback: 'main')."""
    try:
        res = subprocess.run(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=2.0,
        )
        branch = res.stdout.strip()
        if res.returncode == 0 and branch and branch != "HEAD":
            return branch
    except Exception:
        pass
    return "main"


def _extract_repo_name_from_remote_url(url: str) -> Optional[str]:
    """Extracts the bare repository name (without .git suffix) from an HTTP(S) or SSH remote URL."""
    if not url:
        return None
    cleaned = url.strip().rstrip("/")
    if cleaned.endswith(".git"):
        cleaned = cleaned[:-4]
    tail = cleaned.split("/")[-1].split(":")[-1]
    return tail or None


def _resolve_workspace_repo_name(project_root: Path, repo_name: Optional[str] = None) -> str:
    """
    Resolves the target Gitea repository name, preserving any existing non-empty Gitea remote name,
    matching existing GitHub remote names or hyphen/underscore variants on Gitea before falling back
    to the folder name.
    """
    if repo_name:
        return repo_name

    configured_url = _get_configured_gitea_repo_url(project_root)
    configured_name = _extract_repo_name_from_remote_url(configured_url) if configured_url else None

    # Check if the workspace has a github remote (or non-Gitea origin) whose name exists on Gitea
    gh_candidate: Optional[str] = None
    if (project_root / ".git").exists():
        for rem_alias in ("github", "origin"):
            try:
                res = subprocess.run(
                    ["git", "remote", "get-url", rem_alias],
                    cwd=str(project_root),
                    capture_output=True,
                    text=True,
                    timeout=1.5,
                )
                if res.returncode == 0 and "github.com" in res.stdout.lower():
                    gh_candidate = _extract_repo_name_from_remote_url(res.stdout)
                    if gh_candidate:
                        break
            except Exception:
                pass

    if configured_name:
        if gh_candidate and gh_candidate != configured_name:
            try:
                cfg_info = inspect_remote_repository(configured_name)
                gh_info = inspect_remote_repository(gh_candidate)
                if cfg_info.get("empty") and gh_info.get("exists") and not gh_info.get("empty"):
                    return gh_candidate
            except Exception:
                pass
        return configured_name

    if gh_candidate and gh_candidate != project_root.name:
        try:
            gh_info = inspect_remote_repository(gh_candidate)
            if gh_info.get("exists") and not gh_info.get("empty"):
                return gh_candidate
        except Exception:
            pass

    # Check hyphen <-> underscore variant on Gitea if folder name has not been populated yet
    alt_name: Optional[str] = None
    if "_" in project_root.name:
        alt_name = project_root.name.replace("_", "-")
    elif "-" in project_root.name:
        alt_name = project_root.name.replace("-", "_")
    if alt_name:
        try:
            cur_info = inspect_remote_repository(project_root.name)
            if not cur_info.get("exists") or cur_info.get("empty"):
                alt_info = inspect_remote_repository(alt_name)
                if alt_info.get("exists") and not alt_info.get("empty"):
                    return alt_name
        except Exception:
            pass

    return project_root.name


def _prune_stale_origin_refs(project_root: Path) -> None:
    """Deletes cached local refs/remotes/origin/* tracking refs when origin is repointed to a new remote URL."""
    try:
        refs_res = subprocess.run(
            ["git", "for-each-ref", "--format=%(refname)", "refs/remotes/origin/"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=3,
        )
        for ref in refs_res.stdout.splitlines():
            ref = ref.strip()
            if ref:
                subprocess.run(
                    ["git", "update-ref", "-d", ref],
                    cwd=str(project_root),
                    capture_output=True,
                    timeout=2,
                )
    except Exception:
        pass


def setup_workspace_git(
    project_root: Path,
    repo_name: Optional[str] = None,
    configure_remote: bool = True,
) -> bool:
    """Initializes Git in the workspace, heals partial/corrupt .git directories, scrubs legacy tokens, and configures a clean Gitea remote."""
    if not shutil.which("git"):
        return False

    name = _resolve_workspace_repo_name(project_root, repo_name)
    dot_git = project_root / ".git"

    if dot_git.exists():
        _ensure_git_safe_directory(project_root)
        _scrub_workspace_git_config_credentials(project_root)

    needs_init = not (dot_git / "HEAD").exists()
    if not needs_init:
        chk = subprocess.run(
            ["git", "rev-parse", "--is-inside-work-tree"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )
        if chk.returncode != 0:
            needs_init = True

    if needs_init:
        if dot_git.exists():
            _clear_readonly_in_git(dot_git)
        res = subprocess.run(
            ["git", "init", "-b", "main"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )
        if res.returncode != 0:
            res = subprocess.run(
                ["git", "init"],
                cwd=str(project_root),
                capture_output=True,
                text=True,
            )
            if res.returncode != 0:
                return False
            subprocess.run(
                ["git", "symbolic-ref", "HEAD", "refs/heads/main"],
                cwd=str(project_root),
                capture_output=True,
            )
        _ensure_git_safe_directory(project_root)

    subprocess.run(
        ["git", "config", "user.name", "Antigravity"],
        cwd=str(project_root),
        capture_output=True,
    )
    subprocess.run(
        ["git", "config", "user.email", "antigravity@local.dev"],
        cwd=str(project_root),
        capture_output=True,
    )

    gitignore = project_root / ".gitignore"
    if not gitignore.exists():
        default_ignore = (
            "__pycache__/\n"
            "*.pyc\n"
            "*.tmp\n"
            "*.log\n"
            "*.db-shm\n"
            "*.db-wal\n"
            "*.db-journal\n"
            "node_modules/\n"
            ".venv/\n"
            "env/\n"
        )
        try:
            gitignore.write_text(default_ignore, encoding="utf-8")
        except Exception:
            pass

    if not configure_remote:
        return True

    clean_url = ensure_remote_repository(name)
    if clean_url:
        clean_url = _strip_credentials_from_url(clean_url)
        register_git_credential_helper()
        rem_res = subprocess.run(
            ["git", "remote"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )
        remotes = rem_res.stdout.split()
        if "origin" in remotes:
            old_url_res = subprocess.run(
                ["git", "remote", "get-url", "origin"],
                cwd=str(project_root),
                capture_output=True,
                text=True,
            )
            old_url = (old_url_res.stdout or "").strip()
            if old_url and "github.com" in old_url.lower() and "github" not in remotes:
                subprocess.run(
                    ["git", "remote", "add", "github", old_url],
                    cwd=str(project_root),
                    capture_output=True,
                )
            subprocess.run(
                ["git", "remote", "set-url", "origin", clean_url],
                cwd=str(project_root),
                capture_output=True,
            )
            old_norm = (_strip_credentials_from_url(old_url) or "").rstrip("/").lower()
            if old_norm.endswith(".git"):
                old_norm = old_norm[:-4]
            new_norm = clean_url.rstrip("/").lower()
            if new_norm.endswith(".git"):
                new_norm = new_norm[:-4]
            if old_norm and old_norm != new_norm:
                _prune_stale_origin_refs(project_root)
        else:
            subprocess.run(
                ["git", "remote", "add", "origin", clean_url],
                cwd=str(project_root),
                capture_output=True,
            )
        return True
    return False


def _push_tags_to_origin_if_present(project_root: Path) -> None:
    """Pushes local Git tags to local Gitea origin (never to github automatically)."""
    try:
        tag_res = subprocess.run(
            ["git", "tag", "-l"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=3,
        )
        if tag_res.returncode == 0 and tag_res.stdout.strip():
            tag_cmd = _get_git_auth_cmd_prefix() + ["push", "origin", "--tags"]
            subprocess.run(
                tag_cmd,
                cwd=str(project_root),
                capture_output=True,
                text=True,
                timeout=60,
            )
    except Exception:
        pass


def _can_safely_force_replace_remote_snapshot(project_root: Path, branch: str) -> bool:
    """
    Returns True if origin/<branch> diverged solely because an asynchronous background
    mem-save-snapshot auto-commit was pushed right before save_code_commit() amended it
    (i.e. origin/<branch> has an auto-snapshot subject and its parent is an ancestor of HEAD).
    """
    try:
        subprocess.run(
            _get_git_auth_cmd_prefix() + ["fetch", "origin", branch],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=15,
        )
        rem_log = subprocess.run(
            ["git", "log", "-1", "--format=%s%n%ct%n%B", f"origin/{branch}"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=5,
        )
        if rem_log.returncode != 0:
            return False
        lines = rem_log.stdout.splitlines()
        rem_subj = lines[0].strip() if lines else ""
        rem_body = "\n".join(lines[2:]) if len(lines) > 2 else ""
        if not (
            rem_subj.startswith(("[SkillsDB]", "Milestone:", "Synchronize workspace", "Completed "))
            or "Snapshot-Commit: true" in rem_body
            or "Conversation-ID:" in rem_body
        ):
            return False
        anc_chk = subprocess.run(
            ["git", "merge-base", "--is-ancestor", f"origin/{branch}~1", "HEAD"],
            cwd=str(project_root),
            capture_output=True,
            timeout=5,
        )
        return anc_chk.returncode == 0
    except Exception:
        return False


def _sync_secondary_gitea_remote(project_root: Path, branch: str) -> None:
    """If the repository also defines a 'gitea' remote pointing to the local Gitea server, keeps it aligned with origin."""
    try:
        rem_res = subprocess.run(
            ["git", "remote", "get-url", "gitea"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=3,
        )
        if rem_res.returncode == 0 and ("localhost:3000" in rem_res.stdout or "127.0.0.1:3000" in rem_res.stdout):
            subprocess.run(
                _get_git_auth_cmd_prefix() + ["push", "-f", "gitea", branch],
                cwd=str(project_root),
                capture_output=True,
                timeout=30,
            )
    except Exception:
        pass


def _push_to_origin(
    project_root: Path,
    async_push: bool = False,
    _allow_retry: bool = True,
    force_with_lease: bool = False,
) -> bool:
    """Pushes local active branch and tags to Gitea origin using transient in-memory auth headers; auto-heals Gitea service on failure."""
    rem_res = subprocess.run(
        ["git", "remote"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    if "origin" not in rem_res.stdout.split():
        if _is_temp_workspace(project_root) or not is_gitea_configured(project_root):
            return False
        setup_workspace_git(project_root)
    else:
        _scrub_workspace_git_config_credentials(project_root)

    branch = _get_current_branch(project_root)
    push_args = ["push", "--force-with-lease", "-u", "origin", branch] if force_with_lease else ["push", "-u", "origin", branch]
    push_cmd = _get_git_auth_cmd_prefix() + push_args

    try:
        if async_push:
            creation_flags = 0x08000000 if os.name == "nt" else 0
            subprocess.Popen(
                push_cmd,
                cwd=str(project_root),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=creation_flags,
            )
            return True

        push_res = subprocess.run(
            push_cmd,
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=120,
        )
        if push_res.returncode == 0:
            _push_tags_to_origin_if_present(project_root)
            _sync_secondary_gitea_remote(project_root, branch)
            return True

        err_out = (push_res.stderr or "") + (push_res.stdout or "")
        if ("non-fast-forward" in err_out or "fetch first" in err_out or "[rejected]" in err_out) and (
            force_with_lease or _can_safely_force_replace_remote_snapshot(project_root, branch)
        ):
            fwl_cmd = _get_git_auth_cmd_prefix() + ["push", "--force-with-lease", "-u", "origin", branch]
            fwl_res = subprocess.run(
                fwl_cmd,
                cwd=str(project_root),
                capture_output=True,
                text=True,
                timeout=120,
            )
            if fwl_res.returncode == 0:
                _push_tags_to_origin_if_present(project_root)
                _sync_secondary_gitea_remote(project_root, branch)
                return True

        if _allow_retry and not _is_temp_workspace(project_root):
            health = ensure_gitea_online(auto_recover=True, flush_pending=False)
            if health.get("online"):
                setup_workspace_git(project_root)
                retry_cmd = _get_git_auth_cmd_prefix() + push_args
                retry_res = subprocess.run(
                    retry_cmd,
                    cwd=str(project_root),
                    capture_output=True,
                    text=True,
                    timeout=120,
                )
                if retry_res.returncode == 0:
                    _push_tags_to_origin_if_present(project_root)
                    _sync_secondary_gitea_remote(project_root, branch)
                    return True
        return False
    except Exception:
        return False


def _has_unpushed_commits(project_root: Path) -> bool:
    """Checks if local HEAD has commits not yet pushed to origin/<branch> or if the Gitea repository is still empty."""
    rem_res = subprocess.run(
        ["git", "remote"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    if "origin" not in rem_res.stdout.split():
        return True

    head_res = subprocess.run(
        ["git", "rev-parse", "--verify", "HEAD"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    if head_res.returncode != 0:
        return False

    branch = _get_current_branch(project_root)
    rev_res = subprocess.run(
        ["git", "rev-list", "--count", f"origin/{branch}..HEAD"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    if rev_res.returncode != 0:
        return True

    try:
        if int(rev_res.stdout.strip()) > 0:
            return True
    except ValueError:
        return False

    # Guard against stale local refs/remotes/origin/<branch> when the target Gitea repo is still empty
    try:
        repo_name = _resolve_workspace_repo_name(project_root)
        rem_info = inspect_remote_repository(repo_name)
        if rem_info.get("exists") and rem_info.get("empty"):
            _prune_stale_origin_refs(project_root)
            return True
    except Exception:
        pass

    return False


def save_code_commit(
    project_root: Path,
    message: str,
    push: bool = True,
    async_push: bool = False,
    trailers: Optional[Dict[str, str]] = None,
    explicit_message: bool = False,
) -> Dict[str, Any]:
    """
    Stages all modified/new files in the workspace, creates a structured Git commit
    authored by Antigravity <antigravity@local.dev>, and optionally pushes to Gitea.
    """
    result = {
        "success": False,
        "committed": False,
        "amended": False,
        "pushed": False,
        "commit_hash": None,
        "files_changed": 0,
        "changed_files": [],
        "error": None,
    }

    if not project_root or not project_root.exists():
        result["error"] = "Invalid project root"
        return result

    if not shutil.which("git"):
        result["error"] = "Git binary not found in PATH"
        return result

    is_temp = _is_temp_workspace(project_root)

    if not (project_root / ".git" / "HEAD").exists():
        if not setup_workspace_git(project_root, configure_remote=push and not is_temp):
            result["error"] = "Failed to initialize Git repository in workspace"
            return result
    else:
        _ensure_git_safe_directory(project_root)
        _scrub_workspace_git_config_credentials(project_root)
        if not is_temp:
            learn_workspace(project_root)

    try:
        status_res = subprocess.run(
            ["git", "status", "--porcelain"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=10,
        )
        changed_lines = [line.strip() for line in status_res.stdout.splitlines() if line.strip()]
        if not changed_lines:
            rev_res = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                cwd=str(project_root),
                capture_output=True,
                text=True,
            )
            if rev_res.returncode == 0:
                result["commit_hash"] = rev_res.stdout.strip()

            if explicit_message and result["commit_hash"]:
                subj_res = subprocess.run(
                    ["git", "log", "-1", "--format=%s%n%ct%n%B"],
                    cwd=str(project_root),
                    capture_output=True,
                    text=True,
                )
                if subj_res.returncode == 0:
                    log_lines = subj_res.stdout.splitlines()
                    head_subj = log_lines[0].strip() if len(log_lines) >= 1 else ""
                    head_ts = int(log_lines[1].strip()) if len(log_lines) >= 2 and log_lines[1].strip().isdigit() else 0
                    head_body = "\n".join(log_lines[2:]).strip() if len(log_lines) > 2 else ""
                    age_sec = abs(time.time() - head_ts)
                    tag_points_chk = subprocess.run(
                        ["git", "tag", "--points-at", "HEAD"],
                        cwd=str(project_root),
                        capture_output=True,
                        text=True,
                        timeout=5,
                    )
                    head_is_tagged = bool(tag_points_chk.returncode == 0 and tag_points_chk.stdout.strip())
                    is_auto_snap = (
                        head_subj.startswith(("[SkillsDB]", "Milestone:", "Synchronize workspace", "Completed "))
                        or "Snapshot-Commit: true" in head_body
                        or "Conversation-ID:" in head_body
                    )
                    if is_auto_snap and head_subj != message.strip() and age_sec <= 120 and not head_is_tagged:
                        existing_trailers = [
                            tl for tl in head_body.splitlines()
                            if re.match(r"^(Conversation-ID|Snapshot-ID|Snapshot-Commit|Next-Steps):\s+", tl)
                        ]
                        amend_msg = message.strip()
                        if existing_trailers:
                            amend_msg = amend_msg + "\n\n" + "\n".join(existing_trailers)
                        amend_res = subprocess.run(
                            [
                                "git",
                                "-c", "user.name=Antigravity",
                                "-c", "user.email=antigravity@local.dev",
                                "commit", "--amend", "-m", amend_msg,
                            ],
                            cwd=str(project_root),
                            capture_output=True,
                            text=True,
                            timeout=15,
                        )
                        if amend_res.returncode == 0:
                            result["committed"] = True
                            result["amended"] = True
                            new_rev = subprocess.run(
                                ["git", "rev-parse", "HEAD"],
                                cwd=str(project_root),
                                capture_output=True,
                                text=True,
                            )
                            if new_rev.returncode == 0:
                                result["commit_hash"] = new_rev.stdout.strip()

            result["success"] = True
            if push and not is_temp and (result["amended"] or _has_unpushed_commits(project_root)):
                result["pushed"] = _push_to_origin(project_root, async_push=async_push, force_with_lease=bool(result["amended"]))
            return result

        parsed_files = []
        for line in changed_lines:
            fpath = line[2:].strip().strip('"')
            if " -> " in fpath:
                fpath = fpath.split(" -> ")[-1].strip().strip('"')
            if fpath:
                parsed_files.append(fpath)

        result["files_changed"] = len(changed_lines)
        result["changed_files"] = parsed_files

        subprocess.run(
            ["git", "add", "-A"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=15,
        )

        full_msg = message.strip()
        if trailers:
            trailer_lines = [f"{k}: {v}" for k, v in trailers.items() if v]
            if trailer_lines:
                full_msg = full_msg + "\n\n" + "\n".join(trailer_lines)

        commit_res = subprocess.run(
            [
                "git",
                "-c", "user.name=Antigravity",
                "-c", "user.email=antigravity@local.dev",
                "commit",
                "-m",
                full_msg,
            ],
            cwd=str(project_root),
            capture_output=True,
            text=True,
            timeout=15,
        )
        if commit_res.returncode != 0:
            result["error"] = commit_res.stderr.strip() or commit_res.stdout.strip()
            return result

        result["committed"] = True
        result["success"] = True

        rev_res = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )
        if rev_res.returncode == 0:
            result["commit_hash"] = rev_res.stdout.strip()

        if push and not is_temp:
            result["pushed"] = _push_to_origin(project_root, async_push=async_push)

        return result
    except Exception as e:
        result["error"] = str(e)
        return result


def _print_collision_prompt(project_root: Path, rem_info: Dict[str, Any]):
    """Prints an unmissable repository collision warning instructing the agent to ask the user how to proceed."""
    print(f"  [GITEA REPOSITORY COLLISION] Hold on! A repository named '{rem_info['full_name']}' already exists on Gitea ({rem_info['html_url']}).")
    print("  STOP and ask the user how to proceed before pushing:")
    print(f"    1. Use and update the existing repository:  skillsdb gitea-init \"{project_root}\" --use-existing")
    print(f"    2. Create a repository under a new name:    skillsdb gitea-init \"{project_root}\" --name \"<new_repo_name>\"")
    print(f"    3. Recreate/overwrite from scratch:         skillsdb gitea-init \"{project_root}\" --overwrite")


def publish_gitea_release(
    project_root: Path,
    tag_name: Optional[str] = None,
    title: Optional[str] = None,
    notes: Optional[str] = None,
    repo_name: Optional[str] = None,
    prerelease: bool = False,
    sync_first: bool = True,
    sync_github: bool = False,
    target_commit: Optional[str] = None,
) -> Optional[str]:
    """
    Creates or updates a full Gitea release (with Git tag and CHANGELOG.md notes) for a workspace.
    Enforces SemVer 2.0.0 immutability: refuses to move an already published release tag to a newer HEAD
    unless an explicit historical target_commit is specified.
    Returns the HTML URL of the published Gitea release, or None on failure.
    """
    project_root = Path(project_root)
    target_name = _resolve_workspace_repo_name(project_root, repo_name)
    auto_tag, auto_title, auto_notes = _extract_changelog_section(project_root, tag_name)
    final_tag = (tag_name.strip() if tag_name else auto_tag)
    if not final_tag:
        print("  [ERROR] Could not determine version tag (pass a tag or create VERSION / CHANGELOG.md).")
        return None
    if not final_tag.startswith("v") and re.match(r"^[0-9]+\.", final_tag):
        final_tag = f"v{final_tag}"

    if auto_tag != final_tag:
        _, _, matched_notes = _extract_changelog_section(project_root, final_tag)
        if matched_notes:
            auto_notes = matched_notes

    final_title = (title.strip() if title else None) or auto_title or f"{target_name} {final_tag}"
    final_notes = (notes.strip() if notes else None) or auto_notes

    # SemVer 2.0.0 immutability check: prevent overwriting an existing release tag onto a different HEAD commit
    head_res = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    head_sha = head_res.stdout.strip() if head_res.returncode == 0 else ""
    existing_tag_res = subprocess.run(
        ["git", "rev-list", "-n", "1", final_tag],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    existing_tag_sha = existing_tag_res.stdout.strip() if existing_tag_res.returncode == 0 else ""

    head_ver_tag, _, _ = _extract_changelog_section(project_root, None)
    status_chk = subprocess.run(
        ["git", "status", "--porcelain"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    )
    changed_lines = [line.strip() for line in status_chk.stdout.splitlines() if line.strip()]
    changed_files = []
    for line in changed_lines:
        fpath = line[2:].strip().strip('"')
        if " -> " in fpath:
            fpath = fpath.split(" -> ")[-1].strip().strip('"')
        if fpath:
            changed_files.append(fpath)

    only_agents_changed = bool(changed_files) and all(
        f.lower().startswith(".agents/") or f.lower().startswith(".agents\\") or f.lower().endswith("memory.db")
        for f in changed_files
    )
    is_clean_tree = (status_chk.returncode == 0 and not changed_files)

    # 1. If HEAD already matches the target tag:
    # If the working tree is clean or has only internal .agents/memory.db updates,
    # skip sync_first completely! HEAD is already the designated release commit for final_tag.
    # This prevents chore(release) from amending or committing onto an already tagged release commit.
    if existing_tag_sha and head_sha and existing_tag_sha == head_sha:
        if is_clean_tree or only_agents_changed:
            sync_first = False

    # 2. If HEAD has moved ahead of existing_tag_sha, check if the diff is purely internal .agents/ episodic memory:
    diff_chk = subprocess.run(
        ["git", "diff", "--name-only", f"{existing_tag_sha}..{head_sha}"],
        cwd=str(project_root),
        capture_output=True,
        text=True,
    ) if (existing_tag_sha and head_sha and existing_tag_sha != head_sha) else None
    diff_files = [line.strip() for line in diff_chk.stdout.splitlines() if line.strip()] if diff_chk and diff_chk.returncode == 0 else []
    only_agents_diff = bool(diff_files) and all(
        f.lower().startswith(".agents/") or f.lower().startswith(".agents\\") or f.lower().endswith("memory.db")
        for f in diff_files
    )

    if (
        not target_commit
        and existing_tag_sha
        and head_sha
        and existing_tag_sha != head_sha
        and only_agents_diff
        and (is_clean_tree or only_agents_changed)
    ):
        target_commit = existing_tag_sha
        sync_first = False

    # 3. If caller explicitly requested an older historical tag (final_tag != current VERSION/CHANGELOG top tag)
    # on a clean working tree solely to sync its release notes/assets to Gitea/GitHub, pin target_commit to existing_tag_sha.
    if (
        not target_commit
        and existing_tag_sha
        and head_sha
        and existing_tag_sha != head_sha
        and tag_name
        and head_ver_tag
        and final_tag != head_ver_tag
        and is_clean_tree
    ):
        target_commit = existing_tag_sha
        sync_first = False

    if not target_commit and existing_tag_sha and head_sha and existing_tag_sha != head_sha:
        print(
            f"  [SEMVER IMMUTABILITY ERROR] Release tag '{final_tag}' already exists at commit {existing_tag_sha[:7]} "
            f"(current HEAD is {head_sha[:7]})."
        )
        print(
            "  Never overwrite an already published release version in place! "
            "Increment VERSION and CHANGELOG.md to a new SemVer version (MAJOR.MINOR.PATCH) and publish a new release."
        )
        return None

    post_head_sha = head_sha
    if sync_first and not target_commit:
        sync_workspace(
            project_root,
            message=f"chore(release): {final_tag}",
            push=True,
            repo_name=target_name,
            allow_existing=True,
            _skip_auto_release=True,
        )
        post_head_res = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )
        post_head_sha = post_head_res.stdout.strip() if post_head_res.returncode == 0 else ""
        if existing_tag_sha and post_head_sha and existing_tag_sha != post_head_sha:
            print(
                f"  [SEMVER IMMUTABILITY ERROR] Release tag '{final_tag}' already exists at commit {existing_tag_sha[:7]} "
                f"(current HEAD after sync is {post_head_sha[:7]})."
            )
            print(
                "  Never overwrite an already published release version in place! "
                "Increment VERSION and CHANGELOG.md to a new SemVer version (MAJOR.MINOR.PATCH) and publish a new release."
            )
            return None

    if not final_notes:
        log_res = subprocess.run(
            ["git", "log", "-5", "--pretty=format:- %s (%h)"],
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )
        final_notes = log_res.stdout.strip() if log_res.returncode == 0 else f"Release {final_tag}"

    footer = "\n\n---\n*Format based on [Keep a Changelog](https://keepachangelog.com/en/1.1.0/) and [Semantic Versioning](https://semver.org/spec/v2.0.0.html).*"
    if "keepachangelog.com" not in final_notes:
        final_notes += footer

    # Idempotent tag creation: only create the annotated tag if it does not already exist at the target commit,
    # preserving the exact annotated tag object SHA across Gitea and GitHub remotes.
    if not existing_tag_sha:
        tag_cmd = [
            "git",
            "-c", "user.name=Antigravity",
            "-c", "user.email=antigravity@local.dev",
            "tag", "-a", final_tag, "-m", final_title,
        ]
        if target_commit:
            tag_cmd.append(target_commit)
        subprocess.run(
            tag_cmd,
            cwd=str(project_root),
            capture_output=True,
            text=True,
        )

    subprocess.run(
        _get_git_auth_cmd_prefix() + ["push", "origin", final_tag],
        cwd=str(project_root),
        capture_output=True,
        text=True,
        timeout=60,
    )

    config = get_gitea_config()
    token = config.get("token", "")
    user = config.get("user", "")
    base_url = config.get("url", "http://localhost:3000").rstrip("/")
    if not token or not user:
        return None

    headers = {
        "Authorization": f"token {token}",
        "Content-Type": "application/json",
        "User-Agent": "SkillsDB-GiteaSync/1.0",
    }

    existing_rel = None
    try:
        list_req = urllib.request.Request(
            f"{base_url}/api/v1/repos/{user}/{target_name}/releases?limit=50",
            headers=headers,
        )
        with urllib.request.urlopen(list_req, timeout=5.0) as resp:
            rels = json.loads(resp.read().decode("utf-8"))
            for r in rels:
                if r.get("tag_name") == final_tag:
                    existing_rel = r
                    break
    except Exception as e:
        if hasattr(e, "close"):
            try:
                e.close()
            except Exception:
                pass

    is_prerelease = bool(prerelease) or ("-" in final_tag.lstrip("vV"))
    current_branch = _get_current_branch(project_root)
    payload_dict = {
        "tag_name": final_tag,
        "target_commitish": target_commit or (current_branch if is_prerelease else "main"),
        "name": final_title,
        "body": final_notes,
        "draft": False,
        "prerelease": is_prerelease,
    }

    html_url = None
    if existing_rel and existing_rel.get("id"):
        rel_id = existing_rel["id"]
        try:
            patch_req = urllib.request.Request(
                f"{base_url}/api/v1/repos/{user}/{target_name}/releases/{rel_id}",
                data=json.dumps(payload_dict).encode("utf-8"),
                method="PATCH",
                headers=headers,
            )
            with urllib.request.urlopen(patch_req, timeout=8.0) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                html_url = data.get("html_url") or f"{base_url}/{user}/{target_name}/releases/tag/{final_tag}"
                _attach_release_binary_assets(base_url, user, target_name, data.get("id"), final_tag, data.get("assets", []), token, project_root)
                print(f"  [OK] Updated Gitea Release {final_tag}: {html_url}")
        except Exception as e:
            if hasattr(e, "close"):
                try:
                    e.close()
                except Exception:
                    pass

    if not html_url:
        try:
            post_req = urllib.request.Request(
                f"{base_url}/api/v1/repos/{user}/{target_name}/releases",
                data=json.dumps(payload_dict).encode("utf-8"),
                method="POST",
                headers=headers,
            )
            with urllib.request.urlopen(post_req, timeout=8.0) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                html_url = data.get("html_url") or f"{base_url}/{user}/{target_name}/releases/tag/{final_tag}"
                _attach_release_binary_assets(base_url, user, target_name, data.get("id"), final_tag, data.get("assets", []), token, project_root)
                print(f"  [OK] Published Gitea Release {final_tag}: {html_url}")
        except Exception as e:
            if hasattr(e, "close"):
                try:
                    e.close()
                except Exception:
                    pass
            print(f"  [WARN] Could not publish Gitea release {final_tag}: {e}")
            return None

    if sync_github and shutil.which("gh"):
        try:
            with tempfile.NamedTemporaryFile("w", suffix=".md", delete=False, encoding="utf-8") as tf:
                tf.write(final_notes)
                tmp_path = tf.name
            try:
                gh_slug = _resolve_github_repo_slug(project_root)
                repo_args = ["--repo", gh_slug] if gh_slug else []
                prerelease_args = ["--prerelease"] if is_prerelease else []
                subprocess.run(["git", "push", "github", current_branch], cwd=str(project_root), capture_output=True, timeout=30)
                subprocess.run(["git", "push", "github", final_tag], cwd=str(project_root), capture_output=True, timeout=30)
                chk = subprocess.run(["gh", "release", "view", final_tag] + repo_args, cwd=str(project_root), capture_output=True, text=True, timeout=15)
                if chk.returncode == 0:
                    gh_res = subprocess.run(["gh", "release", "edit", final_tag, "--title", final_title, "--notes-file", tmp_path] + prerelease_args + repo_args, cwd=str(project_root), capture_output=True, text=True, timeout=20)
                else:
                    gh_res = subprocess.run(["gh", "release", "create", final_tag, "--title", final_title, "--notes-file", tmp_path] + prerelease_args + repo_args, cwd=str(project_root), capture_output=True, text=True, timeout=20)
                if gh_res.returncode != 0:
                    print(f"  [WARN] Could not publish GitHub release {final_tag}: {(gh_res.stderr or '').strip()}")
            finally:
                Path(tmp_path).unlink(missing_ok=True)
        except Exception:
            pass

    return html_url


def init_workspace_gitea(
    project_root: Path,
    repo_name: Optional[str] = None,
    use_existing: bool = False,
    overwrite: bool = False,
) -> bool:
    """
    Initializes a workspace for Gitea with explicit repository collision detection.
    If a non-empty repository with the target name already exists on Gitea and neither
    use_existing nor overwrite was specified, halts and prompts the agent/user for a decision.
    """
    target_name = _resolve_workspace_repo_name(project_root, repo_name)
    print(f"Initializing Gitea repository '{target_name}' for workspace: {project_root}")

    rem_info = inspect_remote_repository(target_name)
    if rem_info.get("exists") and not rem_info.get("empty"):
        if overwrite:
            delete_remote_repository(target_name)
            print(f"  [OK] Deleted existing repository '{rem_info['full_name']}' for clean re-initialization.")
        elif not use_existing:
            _print_collision_prompt(project_root, rem_info)
            return False

    setup_workspace_git(project_root, repo_name=target_name, configure_remote=True)
    learn_workspace(project_root)
    sync_workspace(
        project_root,
        message=f"Initialize {target_name} on Gitea",
        push=True,
        repo_name=target_name,
        allow_existing=True,
    )
    return True


def sync_workspace(
    project_root: Path,
    message: Optional[str] = None,
    push: bool = True,
    sync_github: bool = False,
    repo_name: Optional[str] = None,
    allow_existing: bool = False,
    allow_unversioned: bool = False,
    _skip_auto_release: bool = False,
) -> bool:
    """Initializes, learns, and synchronizes a specific workspace (including Keep a Changelog releases and collision checks) to Gitea."""
    has_explicit_msg = bool(message and message.strip() and message != "Synchronize workspace code history")
    msg = message or "Synchronize workspace code history"
    target_name = _resolve_workspace_repo_name(project_root, repo_name)
    print(f"Synchronizing workspace: {project_root.name} ({project_root})")

    gitea_active = is_gitea_configured(project_root)
    configured_url = _get_configured_gitea_repo_url(project_root)
    if gitea_active and not configured_url and push and not allow_existing and not _is_temp_workspace(project_root):
        rem_info = inspect_remote_repository(target_name)
        if rem_info.get("exists") and not rem_info.get("empty"):
            setup_workspace_git(project_root, repo_name=target_name, configure_remote=False)
            learn_workspace(project_root)
            _print_collision_prompt(project_root, rem_info)
            return False

    setup_workspace_git(project_root, repo_name=target_name, configure_remote=gitea_active)
    learn_workspace(project_root)
    effective_push = push and gitea_active
    result = save_code_commit(project_root, message=msg, push=effective_push, explicit_message=has_explicit_msg)
    config = get_gitea_config()
    repo_url = _get_configured_gitea_repo_url(project_root) or (
        f"{config['url']}/{config['user']}/{target_name}" if config.get("user") else "local Git"
    )
    if result.get("success"):
        if result.get("committed"):
            action_lbl = "Commit amended" if result.get("amended") else "Commit created"
            print(f"  [OK] {action_lbl}: {result.get('commit_hash', '')[:7]}")
            if not result.get("amended"):
                print(f"  [OK] Files tracked:  {result.get('files_changed', 0)}")
            if result.get("pushed"):
                print(f"  [OK] Pushed successfully to Gitea ({repo_url})")
            elif not gitea_active or not push:
                print("  [OK] Saved locally in Git (Standalone SkillsDB-Only Mode)")
            else:
                print("  [WARN] Commit created locally, push skipped or failed")
        else:
            if result.get("pushed"):
                print(f"  [OK] Flushed pending commits to Gitea (HEAD: {result.get('commit_hash', '')[:7]} | {repo_url})")
            else:
                print(f"  [OK] Already up to date (HEAD: {result.get('commit_hash', '')[:7]} | {repo_url})")

        if push and sync_github and not _is_temp_workspace(project_root):
            try:
                rem_chk = subprocess.run(["git", "remote"], cwd=str(project_root), capture_output=True, text=True, timeout=3)
                if "github" in rem_chk.stdout.split():
                    branch_name = _get_current_branch(project_root)
                    gh_push = subprocess.run(["git", "push", "github", branch_name], cwd=str(project_root), capture_output=True, text=True, timeout=45)
                    if gh_push.returncode == 0:
                        print(f"  [OK] Pushed branch '{branch_name}' to GitHub remote")
            except Exception:
                pass

        if push and not _skip_auto_release and not _is_temp_workspace(project_root) and (project_root / "CHANGELOG.md").exists():
            if not allow_unversioned:
                rel_tags = sync_changelog_releases(project_root, sync_github=sync_github, repo_name=target_name)
                if rel_tags:
                    print(f"  [OK] Synced Keep a Changelog releases: {', '.join(rel_tags)}")
                    print("  [COMPACT MILESTONE TIP] Release state & facts are safely persisted in Gitea and .agents/memory.db. If starting a new feature next, running '/compact' now will shed old context weight with zero knowledge loss.")
            auto_tag, _, _ = _extract_changelog_section(project_root)
            if auto_tag:
                ahead_chk = subprocess.run(
                    ["git", "rev-list", "--count", f"{auto_tag}..HEAD"],
                    cwd=str(project_root),
                    capture_output=True,
                    text=True,
                )
                try:
                    ahead_cnt = int(ahead_chk.stdout.strip()) if ahead_chk.returncode == 0 else 0
                except ValueError:
                    ahead_cnt = 0
                if ahead_cnt > 0:
                    if allow_unversioned:
                        print(
                            f"  [OK] Unversioned upload confirmed (--allow-unversioned): HEAD is {ahead_cnt} commit(s) ahead of {auto_tag} without creating a new release tag."
                        )
                    else:
                        print(
                            f"  [RELEASE REMINDER] HEAD is {ahead_cnt} commit(s) ahead of release {auto_tag}. "
                            f"Increment VERSION + CHANGELOG.md and run 'skillsdb gitea-release' to publish a new release (or pass '--allow-unversioned' only after explicit user confirmation)."
                        )
        return True
    else:
        print(f"  [ERROR] {result.get('error')}")
        return False


def sync_all_workspaces(base_dir: Optional[Path] = None):
    """Discovers and synchronizes all active workspaces across base_dir and registered projects to Gitea."""
    workspaces = discover_all_workspaces(base_dir=base_dir)
    if not workspaces:
        print("No active workspaces discovered to synchronize.")
        return

    print("=" * 60)
    print(f"SkillsDB - Synchronizing {len(workspaces)} discovered workspaces to Gitea")
    print("=" * 60)

    for ws in workspaces:
        print(f"\nProcessing workspace: {ws.name} ({ws})")
        sync_workspace(ws, message=f"SkillsDB automated sync for {ws.name}")
    print(f"\nAll {len(workspaces)} workspaces synchronized with Gitea.")


# =====================================================================
# SECTION: skillsdb.memory.project_memory
# =====================================================================
_HOOK_STATE_FILE = Path(tempfile.gettempdir()) / "skillsdb_hook_state.json"
_VERIFIED_PROJECT_DBS: set[str] = set()


def _resolve_db_file(conn: sqlite3.Connection, db_path: Path = None) -> Path | None:
    """Resolves the filesystem Path for a SQLite connection, returning None for :memory: databases."""
    if db_path:
        return Path(db_path)
    if not conn:
        return None
    try:
        row = conn.execute("PRAGMA database_list;").fetchone()
        if row and row[2]:
            return Path(row[2])
    except sqlite3.Error:
        pass
    return None
_REQUIRED_PROJECT_TABLES = frozenset({
    "project_decisions",
    "session_snapshots",
    "project_facts",
    "fact_history",
    "project_tasks",
    "task_verifications",
    "task_handoffs",
    "project_memory_fts",
})


def _is_protected_non_workspace(path: Path) -> bool:
    """
    Returns True if path is a system/user profile/container/application directory that must never
    be treated as a project workspace (e.g., user home, ~/.gemini, scratch container root,
    root OS temp dir, or %LOCALAPPDATA%/Programs/antigravity).
    """
    return _is_excluded_workspace_path(path, allow_temp_subdirs=True)


def find_project_root(start_path: Path = None) -> Path:
    """Traverses upward to identify project root boundary without crossing user home or system directories."""
    current = Path(os.path.abspath(str(start_path or Path.cwd())))
    if _is_protected_non_workspace(current):
        return current
    project_markers = [
        ".agents", ".git", ".antigravity",
        "package.json", "pyproject.toml", "requirements.txt",
        "pubspec.yaml", "go.mod", "pom.xml", "build.gradle"
    ]
    for parent in [current] + list(current.parents):
        if _is_protected_non_workspace(parent):
            break
        if any((parent / m).exists() for m in project_markers):
            return parent
    return current


def get_project_db_path(project_root: Path = None) -> Path:
    root = project_root or find_project_root()
    return root / ".agents" / "memory.db"


def get_project_connection(project_root: Path = None) -> sqlite3.Connection:
    """Returns a WAL-enabled, memory-mapped SQLite connection to the project memory database."""
    db_path = get_project_db_path(project_root)
    conn = get_connection(db_path, is_project_db=True)
    init_project_db(conn)
    return conn


def _project_schema_ready(conn: sqlite3.Connection) -> bool:
    """Fast read-only check verifying all project memory tables and columns exist without taking a write lock."""
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT name FROM sqlite_master WHERE type IN ('table', 'view') AND name IN "
            "('project_decisions', 'session_snapshots', 'project_facts', 'fact_history', "
            "'project_tasks', 'task_verifications', 'task_handoffs', 'project_memory_fts');"
        )
        found = {row[0] for row in cur.fetchall()}
        if not _REQUIRED_PROJECT_TABLES.issubset(found):
            return False
        cur.execute("PRAGMA table_info(session_snapshots);")
        snap_cols = {row[1] for row in cur.fetchall()}
        if "commit_hash" not in snap_cols:
            return False
        cur.execute("PRAGMA table_info(project_facts);")
        fact_cols = {row[1] for row in cur.fetchall()}
        return "deprecated_at" in fact_cols and "superseded_by" in fact_cols
    except sqlite3.Error:
        return False


def init_project_db(conn: sqlite3.Connection):
    """Initializes tables for architectural decisions, snapshots, project facts, tasks, verifications, and handoffs."""
    db_file = None
    try:
        row = conn.execute("PRAGMA database_list;").fetchone()
        if row and row[2]:
            db_file = os.path.abspath(row[2])
            file_size = os.path.getsize(db_file) if os.path.exists(db_file) else 0
            if file_size > 0 and f"{db_file}:{file_size}" in _VERIFIED_PROJECT_DBS:
                return
    except sqlite3.Error:
        pass

    if _project_schema_ready(conn):
        if db_file and os.path.exists(db_file):
            file_size = os.path.getsize(db_file)
            if file_size > 0:
                _VERIFIED_PROJECT_DBS.add(f"{db_file}:{file_size}")
        return

    cursor = conn.cursor()
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS project_decisions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        category TEXT DEFAULT 'architecture',
        is_active INTEGER DEFAULT 1,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
    );
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS session_snapshots (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        conversation_id TEXT,
        summary TEXT NOT NULL,
        next_steps TEXT,
        files_touched TEXT,
        commit_hash TEXT,
        created_at TEXT NOT NULL
    );
    """)
    # Check if commit_hash column exists in existing databases
    cursor.execute("PRAGMA table_info(session_snapshots);")
    snap_cols = {row[1] for row in cursor.fetchall()}
    if "commit_hash" not in snap_cols:
        cursor.execute("ALTER TABLE session_snapshots ADD COLUMN commit_hash TEXT DEFAULT NULL;")

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS project_facts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        key TEXT UNIQUE NOT NULL,
        value TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        deprecated_at TEXT DEFAULT NULL,
        superseded_by TEXT DEFAULT NULL
    );
    """)
    # Check if deprecated_at column exists in existing databases
    cursor.execute("PRAGMA table_info(project_facts);")
    cols = {row[1] for row in cursor.fetchall()}
    if "deprecated_at" not in cols:
        cursor.execute("ALTER TABLE project_facts ADD COLUMN deprecated_at TEXT DEFAULT NULL;")
    if "superseded_by" not in cols:
        cursor.execute("ALTER TABLE project_facts ADD COLUMN superseded_by TEXT DEFAULT NULL;")

    cursor.execute("""
    CREATE TABLE IF NOT EXISTS fact_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        key TEXT NOT NULL,
        old_value TEXT,
        new_value TEXT NOT NULL,
        reason TEXT,
        created_at TEXT NOT NULL
    );
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS project_tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'in_progress', 'completed', 'blocked')),
        priority TEXT NOT NULL DEFAULT 'med' CHECK(priority IN ('low', 'med', 'high', 'critical')),
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
    );
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS task_verifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        task_id INTEGER NOT NULL,
        verifier_type TEXT NOT NULL,
        passed INTEGER NOT NULL,
        details TEXT,
        created_at TEXT NOT NULL
    );
    """)
    cursor.execute("""
    CREATE TABLE IF NOT EXISTS task_handoffs (
        id TEXT PRIMARY KEY,
        task_id INTEGER,
        source_role TEXT NOT NULL DEFAULT 'lead',
        target_role TEXT NOT NULL DEFAULT 'worker',
        context_variables TEXT,
        notes TEXT,
        status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'accepted', 'completed', 'rejected')),
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
    );
    """)
    cursor.execute("""
    CREATE VIRTUAL TABLE IF NOT EXISTS project_memory_fts USING fts5(
        source_table,
        title_or_key,
        content
    );
    """)
    conn.commit()
    if db_file and os.path.exists(db_file):
        file_size = os.path.getsize(db_file)
        if file_size > 0:
            _VERIFIED_PROJECT_DBS.add(f"{db_file}:{file_size}")


def mem_init(project_root: Path = None):
    root = project_root or find_project_root()
    if _is_protected_non_workspace(root):
        print(f"Skipped: '{root}' is a protected system/profile directory, not a project workspace.")
        return
    db_path = get_project_db_path(root)
    with managed_connection(db_path, is_project_db=True) as conn:
        init_project_db(conn)
    if not _is_temp_workspace(root) and not (root / ".git" / "HEAD").exists():
        setup_workspace_git(root, configure_remote=False)
    learn_workspace(root)
    print(f"Project memory database initialized at: {db_path}")


def mem_save_decision(
    conn: sqlite3.Connection,
    title: str,
    content: str,
    category: str = "architecture",
    db_path: Path = None,
    rationale: str = None,
):
    """Saves an architectural decision using WriterQueue if path is available to prevent lock contention."""
    now_iso = datetime.now(timezone.utc).isoformat()
    full_content = f"{content.strip()}\nRationale: {rationale.strip()}" if rationale and rationale.strip() else content
    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()

    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("UPDATE project_decisions SET is_active = 0, updated_at = ? WHERE title = ? AND is_active = 1;", (now_iso, title))
            cur.execute("""
            INSERT INTO project_decisions (title, content, category, is_active, created_at, updated_at)
            VALUES (?, ?, ?, 1, ?, ?);
            """, (title, full_content, category, now_iso, now_iso))
            row_id = cur.lastrowid
            cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'decision' AND title_or_key = ?;", (title,))
            cur.execute("""
            INSERT INTO project_memory_fts (source_table, title_or_key, content)
            VALUES ('decision', ?, ?);
            """, (title, full_content))
            return row_id
        row_id = wq.execute_write(_write)
        print(f"Project decision saved (ID {row_id}): '{title}'")
        return

    cursor = conn.cursor()
    cursor.execute("UPDATE project_decisions SET is_active = 0, updated_at = ? WHERE title = ? AND is_active = 1;", (now_iso, title))
    cursor.execute("""
    INSERT INTO project_decisions (title, content, category, is_active, created_at, updated_at)
    VALUES (?, ?, ?, 1, ?, ?);
    """, (title, full_content, category, now_iso, now_iso))
    row_id = cursor.lastrowid
    cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'decision' AND title_or_key = ?;", (title,))
    cursor.execute("""
    INSERT INTO project_memory_fts (source_table, title_or_key, content)
    VALUES ('decision', ?, ?);
    """, (title, full_content))
    conn.commit()
    print(f"Project decision saved (ID {row_id}): '{title}'")


def mem_save_snapshot(conn: sqlite3.Connection, summary: str, conversation_id: str = None, next_steps: str = None, files_touched: str = None, db_path: Path = None, silent: bool = False, auto_commit: bool = True):
    """Saves a session milestone snapshot and links it with an automated Git/Gitea commit."""
    now_iso = datetime.now(timezone.utc).isoformat()
    cid = conversation_id or os.environ.get("ANTIGRAVITY_CONVERSATION_ID") or "default"
    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()

    commit_hash = None
    auto_files = files_touched
    if auto_commit:
        root = None
        if target_path:
            p_target = Path(target_path)
            if p_target.parent.name == ".agents":
                root = p_target.parent.parent
            else:
                root = p_target.parent
        else:
            root = find_project_root()

        # Skip auto-commit in temporary unittest directories unless git was explicitly initialized there
        should_commit = bool(root) and (not _is_temp_workspace(root) or (root / ".git" / "HEAD").exists())
        if should_commit:
            learn_workspace(root)
            try:
                trailers = {"Snapshot-Commit": "true"}
                if cid and cid != "default":
                    trailers["Conversation-ID"] = cid
                if next_steps:
                    trailers["Next-Steps"] = next_steps
                gitea_active = is_gitea_configured(root, db_path=DB_PATH)
                c_res = save_code_commit(root, message=summary, push=gitea_active, async_push=False, trailers=trailers)
                if c_res.get("success"):
                    commit_hash = c_res.get("commit_hash")
                    if not auto_files and c_res.get("changed_files"):
                        auto_files = ", ".join(c_res["changed_files"][:15])
                    if not silent and c_res.get("committed"):
                        if c_res.get("pushed"):
                            print(f"Git commit created: {commit_hash[:7]} (pushed to Gitea)")
                        elif not gitea_active:
                            print(f"Git commit created: {commit_hash[:7]} (saved locally)")
                        elif not _is_temp_workspace(root):
                            print(f"Git commit created: {commit_hash[:7]} [WARNING: Gitea push FAILED - server or fileserver unreachable! Commit queued locally for automatic catch-up sync]")
                        else:
                            print(f"Git commit created: {commit_hash[:7]}")
                    if c_res.get("pushed") and not _is_temp_workspace(root):
                        flushed = flush_all_pending_pushes()
                        if flushed and not silent:
                            print(f"Gitea Catch-Up Sync: Flushed pending commits for {', '.join(flushed)}")
            except Exception as e:
                if not silent and not _is_temp_workspace(root):
                    print(f"[WARNING] Gitea synchronization error: {e}")

    fts_parts = [summary]
    if next_steps:
        fts_parts.append(next_steps)
    if auto_files:
        fts_parts.append(auto_files)
    if commit_hash:
        fts_parts.append(commit_hash[:7])
    fts_content = " ".join(fts_parts)

    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("""
            INSERT INTO session_snapshots (conversation_id, summary, next_steps, files_touched, commit_hash, created_at)
            VALUES (?, ?, ?, ?, ?, ?);
            """, (cid, summary, next_steps or "", auto_files or "", commit_hash, now_iso))
            row_id = cur.lastrowid
            cur.execute("""
            INSERT INTO project_memory_fts (source_table, title_or_key, content)
            VALUES ('snapshot', ?, ?);
            """, (cid, fts_content))
            return row_id
        row_id = wq.execute_write(_write)
        if not silent:
            print(f"Session snapshot saved (ID {row_id}) for conversation: {cid}")
            print("  [COMPACT MILESTONE TIP] Milestone state & facts are safely persisted in .agents/memory.db. If starting a new feature next, running '/compact' now will shed old context weight with zero knowledge loss.")
        return

    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO session_snapshots (conversation_id, summary, next_steps, files_touched, commit_hash, created_at)
    VALUES (?, ?, ?, ?, ?, ?);
    """, (cid, summary, next_steps or "", auto_files or "", commit_hash, now_iso))
    row_id = cursor.lastrowid
    cursor.execute("""
    INSERT INTO project_memory_fts (source_table, title_or_key, content)
    VALUES ('snapshot', ?, ?);
    """, (cid, fts_content))
    conn.commit()
    if not silent:
        print(f"Session snapshot saved (ID {row_id}) for conversation: {cid}")


def mem_save_fact(conn: sqlite3.Connection, key: str, value: str, reason: str = None, db_path: Path = None):
    """Saves a key-value fact or configuration item with active reconciliation and tombstone history."""
    now_iso = datetime.now(timezone.utc).isoformat()
    target_path = _resolve_db_file(conn, db_path)

    cursor = conn.cursor() if conn else None
    existing_val = None
    if cursor:
        try:
            cursor.execute("SELECT value FROM project_facts WHERE key = ?;", (key,))
            erow = cursor.fetchone()
            if erow:
                existing_val = erow[0]
        except Exception:
            pass
    if conn and conn.in_transaction:
        conn.commit()

    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("SELECT value FROM project_facts WHERE key = ?;", (key,))
            er = cur.fetchone()
            if er and er[0] != value:
                cur.execute("""
                INSERT INTO fact_history (key, old_value, new_value, reason, created_at)
                VALUES (?, ?, ?, ?, ?);
                """, (key, er[0], value, reason or "superseded", now_iso))
            cur.execute("""
            INSERT OR REPLACE INTO project_facts (key, value, updated_at, deprecated_at, superseded_by)
            VALUES (?, ?, ?, NULL, NULL);
            """, (key, value, now_iso))
            cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (key,))
            cur.execute("""
            INSERT INTO project_memory_fts (source_table, title_or_key, content)
            VALUES ('fact', ?, ?);
            """, (key, value))
        wq.execute_write(_write)
    else:
        if existing_val and existing_val != value:
            cursor.execute("""
            INSERT INTO fact_history (key, old_value, new_value, reason, created_at)
            VALUES (?, ?, ?, ?, ?);
            """, (key, existing_val, value, reason or "superseded", now_iso))
        cursor.execute("""
        INSERT OR REPLACE INTO project_facts (key, value, updated_at, deprecated_at, superseded_by)
        VALUES (?, ?, ?, NULL, NULL);
        """, (key, value, now_iso))
        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (key,))
        cursor.execute("""
        INSERT INTO project_memory_fts (source_table, title_or_key, content)
        VALUES ('fact', ?, ?);
        """, (key, value))
        conn.commit()

    if existing_val and existing_val != value:
        print(f"Project fact updated & reconciled: '{key}' = '{value}' (Previous: '{existing_val}' archived to history)")
    else:
        print(f"Project fact saved: '{key}' = '{value}'")


def mem_deprecate_fact(conn: sqlite3.Connection, key: str, reason: str = "deprecated", db_path: Path = None):
    """Marks a project fact as deprecated/tombstoned so it no longer pollutes the active LLM context."""
    now_iso = datetime.now(timezone.utc).isoformat()
    cursor = conn.cursor()
    cursor.execute("SELECT value FROM project_facts WHERE key = ?;", (key,))
    row = cursor.fetchone()
    if not row:
        print(f"Error: Fact '{key}' not found.")
        return False

    old_val = row[0]
    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()
    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("""
            UPDATE project_facts SET deprecated_at = ? WHERE key = ?;
            """, (now_iso, key))
            cur.execute("""
            INSERT INTO fact_history (key, old_value, new_value, reason, created_at)
            VALUES (?, ?, ?, ?, ?);
            """, (key, old_val, "[TOMBSTONE]", reason, now_iso))
            cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (key,))
        wq.execute_write(_write)
    else:
        cursor.execute("""
        UPDATE project_facts SET deprecated_at = ? WHERE key = ?;
        """, (now_iso, key))
        cursor.execute("""
        INSERT INTO fact_history (key, old_value, new_value, reason, created_at)
        VALUES (?, ?, ?, ?, ?);
        """, (key, old_val, "[TOMBSTONE]", reason, now_iso))
        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (key,))
        conn.commit()

    print(f"Project fact deprecated (tombstoned): '{key}' (Reason: {reason})")
    return True


def mem_fact_history(conn: sqlite3.Connection, key: str = None):
    """Displays the audit trail of fact updates, supersessions, and tombstoning."""
    cursor = conn.cursor()
    query = "SELECT id, key, old_value, new_value, reason, created_at FROM fact_history"
    params = []
    if key:
        query += " WHERE key = ?"
        params.append(key)
    query += " ORDER BY id DESC LIMIT 20;"

    cursor.execute(query, params)
    rows = cursor.fetchall()
    print(f"\n=== PROJECT FACT RECONCILIATION AUDIT LOG ({len(rows)} entries) ===")
    if not rows:
        print("  No fact history records found.")
    else:
        for r in rows:
            print(f"  * [#{r['id']}] '{r['key']}': '{r['old_value']}' -> '{r['new_value']}' ({r['reason']}) [{r['created_at'][:19]}]")
    print()


def mem_reconcile(conn: sqlite3.Connection) -> dict:
    """Scans and reports fact lifecycle health, active vs deprecated items, and history count."""
    cursor = conn.cursor()
    cursor.execute("SELECT COUNT(*) FROM project_facts WHERE deprecated_at IS NULL;")
    active_facts = cursor.fetchone()[0]
    cursor.execute("SELECT COUNT(*) FROM project_facts WHERE deprecated_at IS NOT NULL;")
    deprecated_facts = cursor.fetchone()[0]
    cursor.execute("SELECT COUNT(*) FROM fact_history;")
    history_events = cursor.fetchone()[0]

    report = {
        "active_facts": active_facts,
        "deprecated_facts": deprecated_facts,
        "history_reconciliation_events": history_events,
    }
    print(f"\n=== PROJECT FACT RECONCILIATION REPORT ===")
    print(f"  Active Facts:       {active_facts}")
    print(f"  Tombstoned Facts:   {deprecated_facts}")
    print(f"  Reconciled Events:  {history_events}\n")
    return report


def mem_task_add(conn: sqlite3.Connection, title: str, description: str = "", priority: str = "med", status: str = "pending", db_path: Path = None):
    """Adds a new task to the project task board."""
    now_iso = datetime.now(timezone.utc).isoformat()
    priority = (priority or "med").lower()
    if priority not in ('low', 'med', 'high', 'critical'):
        priority = 'med'
    status = (status or "pending").lower()
    if status not in ('pending', 'in_progress', 'completed', 'blocked'):
        status = 'pending'

    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()
    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("""
            INSERT INTO project_tasks (title, description, status, priority, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?);
            """, (title, description or "", status, priority, now_iso, now_iso))
            row_id = cur.lastrowid
            cur.execute("""
            INSERT INTO project_memory_fts (source_table, title_or_key, content)
            VALUES ('task', ?, ?);
            """, (f"Task #{row_id}: {title}", f"{status} {priority} {description or ''}"))
            return row_id
        row_id = wq.execute_write(_write)
        print(f"Task created (ID {row_id}): [{status.upper()}] ({priority.upper()}) '{title}'")
        return row_id

    cursor = conn.cursor()
    cursor.execute("""
    INSERT INTO project_tasks (title, description, status, priority, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?);
    """, (title, description or "", status, priority, now_iso, now_iso))
    row_id = cursor.lastrowid
    cursor.execute("""
    INSERT INTO project_memory_fts (source_table, title_or_key, content)
    VALUES ('task', ?, ?);
    """, (f"Task #{row_id}: {title}", f"{status} {priority} {description or ''}"))
    conn.commit()
    print(f"Task created (ID {row_id}): [{status.upper()}] ({priority.upper()}) '{title}'")
    return row_id


def mem_task_update(conn: sqlite3.Connection, task_id: int, status: str = None, priority: str = None, title: str = None, description: str = None, db_path: Path = None):
    """Updates the status, priority, title, or description of a task."""
    now_iso = datetime.now(timezone.utc).isoformat()
    cursor = conn.cursor()
    cursor.execute("SELECT id, title, description, status, priority FROM project_tasks WHERE id = ?;", (task_id,))
    row = cursor.fetchone()
    if not row:
        print(f"Error: Task ID {task_id} not found.")
        return False

    new_title = title if title is not None else row["title"]
    new_desc = description if description is not None else row["description"]
    new_status = status.lower() if status else row["status"]
    new_priority = priority.lower() if priority else row["priority"]

    if new_status not in ('pending', 'in_progress', 'completed', 'blocked'):
        print(f"Error: Invalid status '{new_status}'. Allowed: pending, in_progress, completed, blocked")
        return False
    if new_priority not in ('low', 'med', 'high', 'critical'):
        print(f"Error: Invalid priority '{new_priority}'. Allowed: low, med, high, critical")
        return False

    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()
    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("""
            UPDATE project_tasks
            SET title = ?, description = ?, status = ?, priority = ?, updated_at = ?
            WHERE id = ?;
            """, (new_title, new_desc, new_status, new_priority, now_iso, task_id))
            cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{task_id}:%",))
            cur.execute("""
            INSERT INTO project_memory_fts (source_table, title_or_key, content)
            VALUES ('task', ?, ?);
            """, (f"Task #{task_id}: {new_title}", f"{new_status} {new_priority} {new_desc}"))
        wq.execute_write(_write)
    else:
        cursor.execute("""
        UPDATE project_tasks
        SET title = ?, description = ?, status = ?, priority = ?, updated_at = ?
        WHERE id = ?;
        """, (new_title, new_desc, new_status, new_priority, now_iso, task_id))
        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{task_id}:%",))
        cursor.execute("""
        INSERT INTO project_memory_fts (source_table, title_or_key, content)
        VALUES ('task', ?, ?);
        """, (f"Task #{task_id}: {new_title}", f"{new_status} {new_priority} {new_desc}"))
        conn.commit()

    status_change = f" -> [{new_status.upper()}]" if status else ""
    print(f"Task updated (ID {task_id}){status_change}: '{new_title}'")
    return True


def mem_task_list(conn: sqlite3.Connection, status: str = None, as_json: bool = False):
    """Lists tasks filtered by status (or all active tasks by default)."""
    cursor = conn.cursor()
    params = []
    query = "SELECT id, title, description, status, priority, created_at, updated_at FROM project_tasks"
    if status and status.lower() != "all":
        query += " WHERE status = ?"
        params.append(status.lower())
    query += """
    ORDER BY 
        CASE status WHEN 'in_progress' THEN 1 WHEN 'pending' THEN 2 WHEN 'blocked' THEN 3 ELSE 4 END,
        CASE priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'med' THEN 3 ELSE 4 END,
        id ASC;
    """
    cursor.execute(query, params)
    rows = cursor.fetchall()

    if as_json:
        data = [dict(r) for r in rows]
        print(json.dumps(data, indent=2))
        return

    filter_info = f" (Filter: {status.upper()})" if status else ""
    print(f"\n=== PROJECT TASK BOARD{filter_info} ({len(rows)} tasks) ===")
    if not rows:
        print("  No tasks found.")
    else:
        for r in rows:
            stat = r['status'].upper()
            prio = r['priority'].upper()
            desc = f" - {r['description']}" if r['description'] else ""
            print(f"  [#{r['id']}] [{stat:11}] ({prio:8}) {r['title']}{desc}")
    print("=====================================================\n")


def mem_task_clear(conn: sqlite3.Connection, only_completed: bool = True, db_path: Path = None):
    """Clears completed tasks (or all tasks)."""
    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()
    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            if only_completed:
                cur.execute("SELECT id FROM project_tasks WHERE status = 'completed';")
                cids = [r[0] for r in cur.fetchall()]
                cur.execute("DELETE FROM project_tasks WHERE status = 'completed';")
                deleted_rows = cur.rowcount
                for cid_val in cids:
                    cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{cid_val}:%",))
                return deleted_rows
            else:
                cur.execute("DELETE FROM project_tasks;")
                deleted_rows = cur.rowcount
                cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'task';")
                return deleted_rows
        deleted = wq.execute_write(_write)
    else:
        cursor = conn.cursor()
        if only_completed:
            cursor.execute("SELECT id FROM project_tasks WHERE status = 'completed';")
            cids = [r[0] for r in cursor.fetchall()]
            cursor.execute("DELETE FROM project_tasks WHERE status = 'completed';")
            deleted = cursor.rowcount
            for cid_val in cids:
                cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{cid_val}:%",))
        else:
            cursor.execute("DELETE FROM project_tasks;")
            deleted = cursor.rowcount
            cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'task';")
        conn.commit()

    target_str = "completed tasks" if only_completed else "all tasks"
    print(f"Cleared {deleted} {target_str} from project task board.")


def mem_task_delete(conn: sqlite3.Connection, task_id: int, db_path: Path = None) -> bool:
    """Deletes a single task by ID and removes its entry from project_memory_fts."""
    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()
    if target_path and target_path.is_file():
        wq = get_writer_queue(target_path)
        def _write(cur):
            cur.execute("DELETE FROM project_tasks WHERE id = ?;", (task_id,))
            deleted_rows = cur.rowcount
            cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{task_id}:%",))
            return deleted_rows > 0
        deleted = wq.execute_write(_write)
    else:
        cursor = conn.cursor()
        cursor.execute("DELETE FROM project_tasks WHERE id = ?;", (task_id,))
        deleted = cursor.rowcount > 0
        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{task_id}:%",))
        conn.commit()
    if deleted:
        print(f"Task #{task_id} deleted from project task board.")
    else:
        print(f"Error: Task ID {task_id} not found.")
    return deleted


def mem_compact(conn: sqlite3.Connection, summary: str = None, next_steps: str = None, archive_completed: bool = True, project_root: Path = None, db_path: Path = None, silent: bool = False, auto_commit: bool = True):
    """Compacts episodic project memory into a distilled snapshot and vacuums DB."""
    root = project_root or find_project_root()
    flush_journals(root, conn)
    cursor = conn.cursor()

    cursor.execute("SELECT COUNT(*) FROM project_tasks WHERE status = 'completed';")
    completed_count = cursor.fetchone()[0]
    cursor.execute("SELECT COUNT(*) FROM project_tasks WHERE status IN ('pending', 'in_progress', 'blocked');")
    active_count = cursor.fetchone()[0]
    cursor.execute("SELECT COUNT(*) FROM project_decisions WHERE is_active = 1;")
    decisions_count = cursor.fetchone()[0]
    cursor.execute("SELECT COUNT(*) FROM project_facts WHERE deprecated_at IS NULL;")
    facts_count = cursor.fetchone()[0]

    cid = os.environ.get("ANTIGRAVITY_CONVERSATION_ID") or "default"

    default_summary = (
        f"[AUTO-COMPACTED] Project context consolidated. "
        f"{active_count} active tasks, {decisions_count} architectural decisions, {facts_count} facts."
    )
    snap_summary = summary or default_summary

    target_path = _resolve_db_file(conn, db_path)
    if conn and conn.in_transaction:
        conn.commit()

    if archive_completed and completed_count > 0:
        if target_path and target_path.is_file():
            wq = get_writer_queue(target_path)
            def _write_del(cur):
                cur.execute("SELECT id FROM project_tasks WHERE status = 'completed';")
                cids = [r[0] for r in cur.fetchall()]
                cur.execute("DELETE FROM project_tasks WHERE status = 'completed';")
                deleted_rows = cur.rowcount
                for cid_val in cids:
                    cur.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{cid_val}:%",))
                return deleted_rows
            wq.execute_write(_write_del)
        else:
            cursor.execute("SELECT id FROM project_tasks WHERE status = 'completed';")
            cids = [r[0] for r in cursor.fetchall()]
            cursor.execute("DELETE FROM project_tasks WHERE status = 'completed';")
            for cid_val in cids:
                cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'task' AND title_or_key LIKE ?;", (f"Task #{cid_val}:%",))
            conn.commit()

    mem_save_snapshot(conn, snap_summary, conversation_id=cid, next_steps=next_steps, db_path=target_path, silent=silent, auto_commit=auto_commit)

    try:
        conn.execute("PRAGMA incremental_vacuum;")
        conn.commit()
    except Exception:
        pass

    if not silent:
        print("\n=== SESSION AUTO-COMPACTION COMPLETED ===")
        print(f"  Summary:          {snap_summary}")
        if next_steps:
            print(f"  Next Steps:       {next_steps}")
        print(f"  Active Tasks:     {active_count}")
        print(f"  Completed Pruned: {completed_count if archive_completed else 0}")
        print(f"  Active Decisions: {decisions_count}")
        print(f"  Active Facts:     {facts_count}")
        print("=========================================\n")


def mem_get_context(conn: sqlite3.Connection, max_decisions: int = 5, project_root: Path = None):
    """Outputs compact context: active architectural decisions, facts, open tasks, and latest snapshot."""
    root = project_root or find_project_root()
    flush_journals(root, conn)
    cursor = conn.cursor()

    print("\n=== PROJECT MEMORY CONTEXT ===")
    git_telem = get_workspace_git_telemetry(root)
    if git_telem:
        print(f"  {git_telem}")

    cursor.execute("SELECT summary, next_steps, files_touched, commit_hash, created_at FROM session_snapshots ORDER BY id DESC LIMIT 1;")
    last_snap = cursor.fetchone()
    if last_snap:
        dt = last_snap['created_at'][:10]
        print(f"\nLatest Session Milestone ({dt}):")
        print(f"  Summary:    {last_snap['summary']}")
        if "commit_hash" in last_snap.keys() and last_snap['commit_hash']:
            print(f"  Commit:     {last_snap['commit_hash'][:7]}")
        if "files_touched" in last_snap.keys() and last_snap['files_touched']:
            print(f"  Files:      {last_snap['files_touched']}")
        if last_snap['next_steps']:
            print(f"  Next Steps: {last_snap['next_steps']}")

    cursor.execute("""
    SELECT id, title, status, priority, updated_at FROM project_tasks
    WHERE status IN ('pending', 'in_progress', 'blocked')
    ORDER BY 
        CASE status WHEN 'in_progress' THEN 1 WHEN 'pending' THEN 2 ELSE 3 END,
        CASE priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'med' THEN 3 ELSE 4 END,
        id ASC;
    """)
    open_tasks = cursor.fetchall()
    if open_tasks:
        print("\nActive Task Board:")
        for t in open_tasks:
            t_dt = f" [{str(t['updated_at'])[:10]}]" if t['updated_at'] else ""
            print(f"  * [#{t['id']}] [{t['status'].upper():11}] ({t['priority'].upper():8}){t_dt}: {t['title']}")

    cursor.execute("""
    SELECT title, content, category, updated_at FROM project_decisions
    WHERE is_active = 1 ORDER BY updated_at DESC LIMIT ?;
    """, (max_decisions,))
    decisions = cursor.fetchall()
    if decisions:
        print("\nActive Architectural Decisions:")
        for d in decisions:
            d_dt = f" [{str(d['updated_at'])[:10]}]" if d['updated_at'] else ""
            print(f"  * [{d['category'].upper()}]{d_dt} {d['title']}: {d['content']}")

    cursor.execute("SELECT key, value, updated_at FROM project_facts WHERE deprecated_at IS NULL ORDER BY updated_at DESC;")
    facts = cursor.fetchall()
    if facts:
        print("\nProject Facts & Configs:")
        for f in facts:
            f_dt = f" [{str(f['updated_at'])[:10]}]" if f['updated_at'] else ""
            print(f"  * {f['key']}{f_dt}: {f['value']}")

    if not last_snap and not decisions and not facts and not open_tasks:
        print("No memory records found in project database.")
    print("==============================\n")


def mem_search(conn: sqlite3.Connection, query: str):
    """FTS5 search across project facts, decisions, and session milestones."""
    cursor = conn.cursor()
    print(f"\n--- Search results for '{query}' in Project Memory ---\n")
    safe_fts = build_safe_fts_query([query])
    if not safe_fts:
        print("No matching project memory entries.")
        return
    try:
        cursor.execute("""
        SELECT source_table, title_or_key, content
        FROM project_memory_fts
        WHERE project_memory_fts MATCH ?
        LIMIT 10;
        """, (safe_fts,))
        rows = cursor.fetchall()
    except sqlite3.OperationalError:
        rows = []
    if not rows:
        print("No matching project memory entries.")
        return

    for r in rows:
        print(f"[{r['source_table'].upper()}] {r['title_or_key']}")
        print(f"  {r['content'].strip()}\n")


def mem_prune(conn: sqlite3.Connection, max_snapshots: int = 10, max_age_days: int = 30):
    """Reconciles deleted conversation IDs, prunes expired snapshots, and vacuums database."""
    brain_dir = resolve_user_home() / ".gemini" / "antigravity" / "brain"
    existing_cids = set()
    if brain_dir.exists():
        existing_cids = {f.name for f in brain_dir.iterdir() if f.is_dir()}

    cursor = conn.cursor()
    cursor.execute("SELECT id, conversation_id, created_at FROM session_snapshots;")
    snapshots = cursor.fetchall()

    pruned_orphans = 0
    pruned_expired = 0
    now = datetime.now(timezone.utc)

    for s in snapshots:
        cid = s["conversation_id"]
        sid = s["id"]
        if cid and cid != "default" and existing_cids and cid not in existing_cids:
            cursor.execute("DELETE FROM session_snapshots WHERE id = ?;", (sid,))
            pruned_orphans += 1
            continue

        try:
            snap_time = datetime.fromisoformat(s["created_at"].replace("Z", "+00:00"))
            age_days = (now - snap_time).days
            if age_days > max_age_days:
                cursor.execute("DELETE FROM session_snapshots WHERE id = ?;", (sid,))
                pruned_expired += 1
        except Exception:
            pass

    cursor.execute("SELECT id FROM session_snapshots ORDER BY id DESC;")
    all_remaining = [r[0] for r in cursor.fetchall()]
    if len(all_remaining) > max_snapshots:
        excess_ids = all_remaining[max_snapshots:]
        cursor.executemany("DELETE FROM session_snapshots WHERE id = ?;", [(eid,) for eid in excess_ids])
        pruned_expired += len(excess_ids)

    if pruned_orphans > 0 or pruned_expired > 0:
        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'snapshot';")
        cursor.execute("SELECT conversation_id, summary, next_steps, files_touched, commit_hash FROM session_snapshots ORDER BY id ASC;")
        for rem in cursor.fetchall():
            rem_cid = rem["conversation_id"] or "default"
            parts = [rem["summary"] or ""]
            if rem["next_steps"]:
                parts.append(rem["next_steps"])
            if rem["files_touched"]:
                parts.append(rem["files_touched"])
            if rem["commit_hash"]:
                parts.append(rem["commit_hash"][:7])
            cursor.execute(
                "INSERT INTO project_memory_fts (source_table, title_or_key, content) VALUES ('snapshot', ?, ?);",
                (rem_cid, " ".join(p for p in parts if p)),
            )

    conn.commit()
    cursor.execute("PRAGMA incremental_vacuum;")
    conn.commit()
    print(f"Project memory pruned: {pruned_orphans} orphaned conversation snapshots removed, {pruned_expired} old snapshots trimmed. Vacuum complete.")


def _extract_hook_user_message(payload: dict) -> str:
    """Extracts the current user message from an Antigravity v2.28.0+ hook payload."""
    if not isinstance(payload, dict):
        return ""
    for key in ("userMessage", "userPrompt", "prompt", "message"):
        val = payload.get(key)
        if isinstance(val, str) and val.strip():
            return val.strip()
        if isinstance(val, dict):
            for subkey in ("userMessage", "content", "text", "prompt"):
                subval = val.get(subkey)
                if isinstance(subval, str) and subval.strip():
                    return subval.strip()
    return ""


def analyze_conversation_epochs_and_scope(
    cid: str = None,
    active_workspace: Path = None,
    db_path: Path = DB_PATH,
    brain_dir: Path = None,
    epoch_gap_hours: float = 4.0,
) -> dict:
    """
    Slices a conversation's transcript.jsonl into temporal epochs (separated by >4h gaps
    or UTC date changes) and detects foreign workspace mentions in historical epochs to
    prevent cross-project context bleeding across multi-day conversations without adding
    extra conversation_id columns to SQLite tables.
    """
    result = {
        "cid": str(cid or ""),
        "epoch_key": "epoch-1",
        "epoch_count": 0,
        "active_epoch": None,
        "epochs": [],
        "foreign_project_mentions": [],
        "max_step_index": 0,
        "step_bucket": 0,
        "recent_read_streak": 0,
        "recent_poll_streak": 0,
        "repeated_file_warning": "",
        "inferred_workspace": None,
        "steps_since_compaction": 0,
        "epoch_touched_files": [],
        "subagent_findings": [],
    }
    if not cid:
        return result

    b_dir = Path(brain_dir) if brain_dir else (resolve_user_home() / ".gemini" / "antigravity" / "brain")
    t_file = b_dir / str(cid) / ".system_generated" / "logs" / "transcript.jsonl"
    if not t_file.exists():
        return result

    user_steps = []
    recent_lines = []
    subagent_raw_lines = []
    steps_since_compaction = 0
    max_step_idx = 0
    try:
        with open(t_file, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                steps_since_compaction += 1
                if "<CONTEXT_SUMMARY>" in line:
                    steps_since_compaction = 0
                recent_lines.append(line)
                if len(recent_lines) > 30:
                    recent_lines.pop(0)
                if '"SYSTEM_MESSAGE"' in line and "sender=" in line and "/task-" not in line:
                    subagent_raw_lines.append(line)
                    if len(subagent_raw_lines) > 5:
                        subagent_raw_lines.pop(0)
                if '"USER_INPUT"' not in line and '"USER_EXPLICIT"' not in line:
                    continue
                try:
                    d = json.loads(line)
                except Exception:
                    continue
                s_idx = int(d.get("step_index") or 0)
                if s_idx > max_step_idx:
                    max_step_idx = s_idx
                if d.get("type") != "USER_INPUT" and d.get("source") != "USER_EXPLICIT":
                    continue
                ts_str = str(d.get("created_at") or "").strip()
                if not ts_str:
                    continue
                try:
                    ts_dt = datetime.fromisoformat(ts_str.replace("Z", "+00:00"))
                except Exception:
                    ts_dt = None
                user_steps.append({
                    "step_index": int(d.get("step_index") or 0),
                    "created_at": ts_str,
                    "date": ts_str[:10],
                    "dt": ts_dt,
                    "content": str(d.get("content") or ""),
                })
    except Exception:
        return result

    read_streak = 0
    poll_streak = 0
    read_file_counts = {}
    candidate_roots = {}

    bs = chr(92)
    def _record_candidate_path(raw_p: str):
        try:
            cleaned = raw_p.strip().rstrip(',.;:)]}"' + "'")
            while (bs + bs) in cleaned:
                cleaned = cleaned.replace(bs + bs, bs)
            if len(cleaned) < 4:
                return
            low_c = cleaned.lower().replace('/', bs)
            if ((bs + 'appdata' + bs) in low_c and (bs + 'temp' + bs) not in low_c) or (bs + 'windows' + bs) in low_c or (bs + 'program files') in low_c:
                return
            if (bs + '.gemini' + bs) in low_c and (bs + '.gemini' + bs + 'antigravity' + bs + 'scratch' + bs) not in low_c:
                return
            p_obj = Path(cleaned)
            probe = p_obj if p_obj.exists() else (p_obj.parent if p_obj.parent.exists() else None)
            if not probe:
                return
            c_root = find_project_root(probe if probe.is_dir() else probe.parent)
            if c_root and len(c_root.parts) >= 2 and c_root.exists() and not _is_protected_non_workspace(c_root):
                key = str(c_root)
                weight = 3 if (c_root / '.agents' / 'memory.db').exists() else (2 if (c_root / '.git').exists() else 1)
                candidate_roots[key] = candidate_roots.get(key, 0) + weight
        except Exception:
            pass

    win_path_re = re.compile(r'[A-Za-z]:[\\/][^\s"\'<>|*?]+')
    path_arg_re = re.compile(r'"Path"\s*:\s*"([^"]+)"')
    for rline in recent_lines:
        if '"step_index"' in rline:
            try:
                rd = json.loads(rline)
                rs_idx = int(rd.get('step_index') or 0)
                if rs_idx > max_step_idx:
                    max_step_idx = rs_idx
            except Exception:
                pass
        if '"read_file"' in rline:
            read_streak += 1
            for m_path in path_arg_re.findall(rline):
                fname = Path(m_path.replace(bs + bs, bs)).name
                if fname:
                    read_file_counts[fname] = read_file_counts.get(fname, 0) + 1
                _record_candidate_path(m_path)
        if '"manage_task"' in rline and '"status"' in rline:
            poll_streak += 1
        if not active_workspace and ('"PLANNER_RESPONSE"' in rline or '"USER_INPUT"' in rline or '"USER_EXPLICIT"' in rline):
            for m_win in win_path_re.findall(rline):
                _record_candidate_path(m_win)

    if not active_workspace and user_steps:
        for ust in user_steps[-3:]:
            for m_win in win_path_re.findall(ust.get('content', '')):
                _record_candidate_path(m_win)

    if not active_workspace and candidate_roots:
        best_root = max(candidate_roots.items(), key=lambda kv: kv[1])[0]
        result["inferred_workspace"] = best_root

    if read_file_counts:
        top_fname, top_cnt = max(read_file_counts.items(), key=lambda kv: kv[1])
        if top_cnt >= 3:
            result["repeated_file_warning"] = f"{top_fname} ({top_cnt}x in recent steps)"

    touched_files = []
    edit_path_re = re.compile(r'"(?:Path|TargetFile|AbsolutePath)"\s*:\s*"([^"]+)"')
    for rline in recent_lines:
        for mp in edit_path_re.findall(rline):
            fn = Path(mp.replace(bs + bs, bs)).name
            if fn and fn not in touched_files and not fn.endswith(".log"):
                touched_files.append(fn)
                if len(touched_files) >= 8:
                    break

    parsed_subagents = []
    if user_steps:
        sub_re = re.compile(r"sender=([0-9a-fA-F\-]{8,})\s+priority=\S+\s+content=(.*?)(?:</SYSTEM_MESSAGE>|$)", re.DOTALL)
        for sline in subagent_raw_lines:
            try:
                sd = json.loads(sline)
                s_idx = int(sd.get("step_index") or 0)
                if s_idx <= 2:
                    continue
                scontent = str(sd.get("content") or "")
                m_sub = sub_re.search(scontent)
                if m_sub:
                    sender_id = m_sub.group(1)[:8]
                    body = m_sub.group(2).strip()
                    body_clean = re.sub(r"```.*?```", " ", body, flags=re.DOTALL)
                    body_clean = re.sub(r"\s+", " ", body_clean).strip()
                    if body_clean:
                        parsed_subagents.append({
                            "step_index": s_idx,
                            "sender": sender_id,
                            "summary": body_clean[:280],
                        })
            except Exception:
                pass

    result["max_step_index"] = max_step_idx
    result["step_bucket"] = max_step_idx // 50
    result["recent_read_streak"] = read_streak
    result["recent_poll_streak"] = poll_streak
    result["steps_since_compaction"] = steps_since_compaction
    result["epoch_touched_files"] = touched_files
    result["subagent_findings"] = parsed_subagents

    if not user_steps:
        return result

    raw_epochs = []
    curr = {
        "epoch_index": 1,
        "date": user_steps[0]["date"],
        "start_ts": user_steps[0]["created_at"],
        "end_ts": user_steps[0]["created_at"],
        "step_start": user_steps[0]["step_index"],
        "step_end": user_steps[0]["step_index"],
        "turn_count": 1,
        "steps": [user_steps[0]],
    }
    prev_step = user_steps[0]
    gap_seconds = max(0.25, float(epoch_gap_hours)) * 3600.0

    for st in user_steps[1:]:
        new_epoch = False
        if st["date"] != prev_step["date"]:
            new_epoch = True
        elif st["dt"] is not None and prev_step["dt"] is not None:
            if (st["dt"] - prev_step["dt"]).total_seconds() > gap_seconds:
                new_epoch = True
        if new_epoch:
            raw_epochs.append(curr)
            curr = {
                "epoch_index": len(raw_epochs) + 1,
                "date": st["date"],
                "start_ts": st["created_at"],
                "end_ts": st["created_at"],
                "step_start": st["step_index"],
                "step_end": st["step_index"],
                "turn_count": 1,
                "steps": [st],
            }
        else:
            curr["end_ts"] = st["created_at"]
            curr["step_end"] = st["step_index"]
            curr["turn_count"] += 1
            curr["steps"].append(st)
        prev_step = st
    raw_epochs.append(curr)

    clean_epochs = [{k: v for k, v in ep.items() if k != "steps"} for ep in raw_epochs]
    result["epochs"] = clean_epochs
    result["epoch_count"] = len(clean_epochs)
    result["active_epoch"] = clean_epochs[-1]
    result["epoch_key"] = f"epoch-{len(clean_epochs)}-{clean_epochs[-1]['date']}"

    # Cross-project contamination guard across historical epochs (epochs[:-1])
    if len(raw_epochs) > 1:
        stop_tokens = {
            "antigravity", "workspace", "workspaces", "project", "projects", "python",
            "gemini", "skillsdb", "gitea", "github", "users", "appdata", "local",
            "roaming", "program", "programs", "source", "repos", "documents", "desktop",
            "scratch", "default", "master", "main", "build", "release", "enterprise",
            "portable", "service", "server", "client", "system", "config", "database",
        }
        active_norm = ""
        active_tokens = set()
        if active_workspace:
            try:
                active_norm = os.path.normcase(os.path.abspath(str(active_workspace)))
                for part in Path(active_norm).parts:
                    p_clean = part.strip("\\/:").lower()
                    if p_clean:
                        active_tokens.add(p_clean)
                        for sub in p_clean.replace("-", "_").split("_"):
                            if len(sub) >= 4:
                                active_tokens.add(sub)
            except Exception:
                pass

        learned_ws = get_learned_workspaces(db_path=db_path, prune_missing=False)
        ws_paths_iter = learned_ws.values() if isinstance(learned_ws, dict) else learned_ws
        foreign_candidates = []
        for ws_str in ws_paths_iter:
            try:
                ws_norm = os.path.normcase(os.path.abspath(ws_str))
            except Exception:
                continue
            if active_norm and ws_norm == active_norm:
                continue
            ws_p = Path(ws_str)
            ws_name = ws_p.name
            parent_name = ws_p.parent.name if ws_p.parent else ""
            label = f"{ws_name} ({parent_name})" if parent_name and parent_name.lower() not in stop_tokens else ws_name
            tokens = set()
            if len(ws_name) >= 5 and ws_name.lower() not in stop_tokens and ws_name.lower() not in active_tokens:
                tokens.add(ws_name.lower())
            for raw_part in (ws_name, parent_name):
                for sub in raw_part.replace("-", "_").split("_"):
                    s_low = sub.lower()
                    if len(s_low) >= 5 and s_low not in stop_tokens and s_low not in active_tokens:
                        tokens.add(s_low)
            if tokens:
                foreign_candidates.append((label, sorted(tokens, key=len, reverse=True)))

        seen_mentions = set()
        mentions = []
        for ep in raw_epochs[:-1]:
            for st in ep["steps"]:
                text_low = st["content"].lower()
                if not text_low:
                    continue
                for label, tok_list in foreign_candidates:
                    for tok in tok_list:
                        if tok in text_low:
                            m_key = (ep["date"], label)
                            if m_key not in seen_mentions:
                                seen_mentions.add(m_key)
                                mentions.append({
                                    "date": ep["date"],
                                    "epoch_index": ep["epoch_index"],
                                    "project": label,
                                    "matched_token": tok,
                                    "step_index": st["step_index"],
                                })
                            break
        result["foreign_project_mentions"] = mentions

    return result


def handle_pre_invocation_hook():
    """
    Handles Antigravity PreInvocation lifecycle hook with 100% autonomy:
    1. Runtime Model Concurrency Profile (Ultra vs Standard).
    2. Temporal Epoch Slicing & Cross-Project Contamination Guard.
    3. Autonomous Directory Scoping: Auto-detects domain markers (Flutter, BigQuery, Docker, etc.) and injects micro-skills.
    4. Autonomous Auto-Compaction: Prunes completed tasks and consolidates memory if threshold reached.
    5. Deterministic Task Board: Injects active tasks with states (pending, in_progress, blocked) and priorities.
    6. Episodic Decisions, Facts, and latest Milestone Snapshot with [YYYY-MM-DD] timestamps.
    """
    try:
        payload_raw = sys.stdin.read()
        payload = json.loads(payload_raw) if payload_raw.strip() else {}
    except Exception:
        payload = {}

    invocation_num = payload.get("invocationNum", 1)
    if invocation_num is not None and invocation_num > 1:
        print(json.dumps({"injectSteps": []}))
        return

    workspace_paths = payload.get("workspacePaths", [])
    proj_path = Path(workspace_paths[0]) if workspace_paths else None
    has_valid_workspace = bool(proj_path) and not _is_protected_non_workspace(proj_path)
    root_path = find_project_root(proj_path) if has_valid_workspace else None
    if root_path and _is_protected_non_workspace(root_path):
        has_valid_workspace = False
        root_path = None
    db_path = get_project_db_path(root_path) if (has_valid_workspace and root_path) else None

    cid = payload.get("conversationId")
    brain_dir_override = Path(payload["brainDir"]) if payload.get("brainDir") else None
    central_db_override = Path(payload["dbPath"]) if payload.get("dbPath") else DB_PATH
    epoch_info = analyze_conversation_epochs_and_scope(
        cid=cid,
        active_workspace=root_path,
        db_path=central_db_override,
        brain_dir=brain_dir_override,
    )

    explicit_ws_key = str(root_path) if (has_valid_workspace and root_path) else "__no_workspace__"

    # Auto-infer active project workspace from transcript file paths when no IDE workspace is open (workspacePaths == [])
    if not has_valid_workspace and epoch_info.get("inferred_workspace"):
        inferred_p = Path(epoch_info["inferred_workspace"])
        if inferred_p.exists() and not _is_protected_non_workspace(inferred_p):
            root_path = inferred_p
            has_valid_workspace = True
            proj_path = root_path
            db_path = get_project_db_path(root_path)

    today_utc = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    active_ep_date = epoch_info["active_epoch"]["date"] if epoch_info.get("active_epoch") else today_utc

    def _collect_project_memory_lines() -> tuple[list[str], int]:
        mem_lines = []
        facts_cnt = 0
        if not (has_valid_workspace and root_path and db_path and db_path.exists()):
            return mem_lines, facts_cnt
        try:
            with managed_connection(db_path, is_project_db=True) as conn:
                init_project_db(conn)
                cursor = conn.cursor()
                now_iso_hook = datetime.now(timezone.utc).isoformat()
                # 1. Auto-persist research subagent findings into .agents/memory.db so compactions never lose them,
                #    while rotating older subagent_finding_step_* rows so at most 2 occupy the active 12-fact window.
                inserted_sf = False
                for sf in (epoch_info.get("subagent_findings") or []):
                    sf_key = f"subagent_finding_step_{sf['step_index']}"
                    cursor.execute("SELECT 1 FROM project_facts WHERE key = ?;", (sf_key,))
                    if not cursor.fetchone():
                        sf_val = f"[Subagent {sf['sender']}] {sf['summary']}"
                        cursor.execute(
                            "INSERT OR REPLACE INTO project_facts (key, value, updated_at, deprecated_at, superseded_by) VALUES (?, ?, ?, NULL, NULL);",
                            (sf_key, sf_val, now_iso_hook),
                        )
                        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (sf_key,))
                        cursor.execute(
                            "INSERT INTO project_memory_fts (source_table, title_or_key, content) VALUES ('fact', ?, ?);",
                            (sf_key, sf_val),
                        )
                        inserted_sf = True
                if inserted_sf:
                    cursor.execute(
                        "SELECT key FROM project_facts WHERE key LIKE 'subagent_finding_step_%' AND deprecated_at IS NULL ORDER BY updated_at DESC, id DESC;"
                    )
                    active_sf_keys = [r[0] for r in cursor.fetchall()]
                    for stale_sf_key in active_sf_keys[2:]:
                        cursor.execute(
                            "UPDATE project_facts SET deprecated_at = ?, superseded_by = ? WHERE key = ?;",
                            (now_iso_hook, active_sf_keys[0], stale_sf_key),
                        )
                        cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (stale_sf_key,))
                    conn.commit()
                # 2. Auto-checkpoint active working set before auto-compaction when steps_since_compaction >= 150
                if epoch_info.get("steps_since_compaction", 0) >= 150 and epoch_info.get("epoch_touched_files"):
                    ws_key_fact = "auto_checkpoint_working_set"
                    ws_val_fact = (
                        f"Step {epoch_info.get('max_step_index', 0)} ({epoch_info.get('steps_since_compaction', 0)} uncompacted steps) active files: "
                        + ", ".join(epoch_info["epoch_touched_files"])
                    )
                    cursor.execute(
                        "INSERT OR REPLACE INTO project_facts (key, value, updated_at, deprecated_at, superseded_by) VALUES (?, ?, ?, NULL, NULL);",
                        (ws_key_fact, ws_val_fact, now_iso_hook),
                    )
                    cursor.execute("DELETE FROM project_memory_fts WHERE source_table = 'fact' AND title_or_key = ?;", (ws_key_fact,))
                    cursor.execute(
                        "INSERT INTO project_memory_fts (source_table, title_or_key, content) VALUES ('fact', ?, ?);",
                        (ws_key_fact, ws_val_fact),
                    )
                    conn.commit()
                cursor.execute("SELECT COUNT(*) FROM project_tasks WHERE status = 'completed';")
                completed_count = cursor.fetchone()[0]
                if completed_count >= 3:
                    mem_compact(conn, summary=f"[AUTO-COMPACTED] Pruned {completed_count} completed tasks and consolidated state.", archive_completed=True, project_root=root_path, db_path=db_path, silent=True, auto_commit=False)

                git_telem = get_workspace_git_telemetry(root_path, auto_recover=False)
                if git_telem:
                    mem_lines.append(git_telem)

                cursor.execute("""
                SELECT id, title, status, priority, updated_at FROM project_tasks
                WHERE status IN ('pending', 'in_progress', 'blocked')
                ORDER BY 
                    CASE status WHEN 'in_progress' THEN 1 WHEN 'pending' THEN 2 ELSE 3 END,
                    CASE priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'med' THEN 3 ELSE 4 END,
                    id ASC LIMIT 5;
                """)
                open_tasks = cursor.fetchall()
                if open_tasks:
                    if mem_lines:
                        mem_lines.append("")
                    mem_lines.append("Active Task Board (Deterministic Progress):")
                    for t in open_tasks:
                        t_date = str(t["updated_at"] or "")[:10]
                        t_tag = f" [{t_date}]" if t_date else ""
                        mem_lines.append(f"  * [#{t['id']}] [{t['status'].upper():11}] ({t['priority'].upper():8}){t_tag}: {t['title']}")

                cursor.execute("SELECT id, source_role, target_role, notes FROM task_handoffs WHERE status = 'pending' ORDER BY created_at DESC LIMIT 3;")
                pending_hos = cursor.fetchall()
                if pending_hos:
                    if mem_lines:
                        mem_lines.append("")
                    mem_lines.append("Pending Agent Handoffs (Delegation Queue):")
                    for ho in pending_hos:
                        note_s = f" - '{ho['notes'][:60]}...'" if ho['notes'] else ""
                        mem_lines.append(f"  * [{ho['id']}] [{ho['source_role']}] -> [{ho['target_role']}]{note_s}")

                cursor.execute("SELECT key, value, updated_at FROM project_facts WHERE deprecated_at IS NULL ORDER BY updated_at DESC LIMIT 12;")
                facts = cursor.fetchall()
                facts_cnt = len(facts)
                if facts:
                    if mem_lines:
                        mem_lines.append("")
                    mem_lines.append("Project Facts & Configs (.agents/memory.db):")
                    for f in facts:
                        f_date = str(f["updated_at"] or "")[:10]
                        f_tag = f" [{f_date}]" if f_date else ""
                        mem_lines.append(f"  * {f['key']}{f_tag}: {f['value']}")

                cursor.execute("SELECT title, content, updated_at FROM project_decisions WHERE is_active = 1 ORDER BY updated_at DESC LIMIT 5;")
                decs = cursor.fetchall()
                if decs:
                    if mem_lines:
                        mem_lines.append("")
                    mem_lines.append("Active Architectural Decisions:")
                    for d in decs:
                        d_date = str(d["updated_at"] or "")[:10]
                        d_tag = f" [{d_date}]" if d_date else ""
                        mem_lines.append(f"  * [{d['title']}]{d_tag}: {d['content']}")

                cursor.execute("SELECT summary, next_steps, files_touched, commit_hash, created_at FROM session_snapshots ORDER BY id DESC LIMIT 1;")
                snap = cursor.fetchone()
                if snap:
                    if mem_lines:
                        mem_lines.append("")
                    snap_date = str(snap["created_at"] or "")[:10]
                    ep_marker = " [ACTIVE EPOCH]" if snap_date and snap_date >= active_ep_date else ""
                    snap_hdr = f"Latest Project Milestone Snapshot ({snap_date}{ep_marker}):" if snap_date else "Latest Project Milestone Snapshot:"
                    mem_lines.append(snap_hdr)
                    mem_lines.append(f"  Summary: {snap['summary']}")
                    if "commit_hash" in snap.keys() and snap["commit_hash"]:
                        mem_lines.append(f"  Commit: {snap['commit_hash'][:7]}")
                    if "files_touched" in snap.keys() and snap["files_touched"]:
                        mem_lines.append(f"  Files Touched: {snap['files_touched']}")
                    if snap["next_steps"]:
                        mem_lines.append(f"  Next Steps: {snap['next_steps']}")
        except Exception:
            pass
        return mem_lines, facts_cnt

    # Always run fast (<0.2ms) Windows UTF-8 manifest self-healing check before hook
    # deduplication so mid-conversation Antigravity IDE updates ('Restart to Update')
    # immediately restore wiped .manifest files on the very next turn.
    utf8_healed = ensure_windows_utf8_manifests()
    _sync_builtin_fn = globals().get("sync_builtin_skills")
    if not _sync_builtin_fn:
        try:
            import importlib
            _sync_builtin_fn = getattr(importlib.import_module("skillsdb.updater.merger"), "sync_builtin_skills", None)
        except Exception:
            _sync_builtin_fn = None

    model_hint = payload.get("modelName") or payload.get("model")
    routing_dec = None
    current_routing_sig = ""
    try:
        routing_dec = compute_routing_decision(
            cid=cid,
            db_path=central_db_override,
            model_name_hint=model_hint,
            brain_dir=brain_dir_override,
        )
        current_routing_sig = (
            f"{routing_dec['account_tier']}:{routing_dec['effective_mode']}:{routing_dec['state']['model_name']}"
        )
    except Exception:
        routing_dec = None

    # Deduplicate per (conversationId, workspace, temporal_epoch) so Antigravity's
    # per-tool-step PreInvocation calls within the same session epoch do not bloat
    # transcript.jsonl, while a new day, >4h temporal epoch, mid-session model/effort switch,
    # or every 50-step bucket automatically re-hydrates the Turn-Economy Guardrail,
    # Multi-Pool Quota Router, and .agents/memory.db context.
    workspace_key = explicit_ws_key
    dedup_token = f"{workspace_key}@{epoch_info['epoch_key']}"
    if cid:
        try:
            state = {}
            if _HOOK_STATE_FILE.exists():
                try:
                    loaded = json.loads(_HOOK_STATE_FILE.read_text(encoding="utf-8"))
                    if isinstance(loaded, dict):
                        state = loaded
                except Exception:
                    state = {}
            if state.get(cid) == dedup_token:
                drift_bucket = epoch_info.get("step_bucket", 0)
                read_streak = epoch_info.get("recent_read_streak", 0)
                poll_streak = epoch_info.get("recent_poll_streak", 0)
                rep_file = epoch_info.get("repeated_file_warning", "")
                max_step = epoch_info.get("max_step_index", 0)
                drift_key = f"{cid}:drift_bucket"
                anomaly_key = f"{cid}:anomaly_step"
                routing_sig_key = f"{cid}:routing_sig"
                last_bucket = state.get(drift_key, 0)
                last_anomaly = state.get(anomaly_key, -100)
                prev_routing_sig = state.get(routing_sig_key, "")
                need_drift_guard = False
                need_routing_refresh = False
                if drift_bucket > last_bucket:
                    state[drift_key] = drift_bucket
                    need_drift_guard = True
                    need_routing_refresh = True
                elif (read_streak >= 6 or poll_streak >= 2 or bool(rep_file)) and (max_step - last_anomaly >= 25):
                    state[anomaly_key] = max_step
                    need_drift_guard = True
                    need_routing_refresh = True
                if current_routing_sig and prev_routing_sig != current_routing_sig:
                    state[routing_sig_key] = current_routing_sig
                    if prev_routing_sig:
                        need_routing_refresh = True
                if need_drift_guard or need_routing_refresh or (current_routing_sig and not prev_routing_sig):
                    try:
                        _HOOK_STATE_FILE.write_text(json.dumps(state), encoding="utf-8")
                    except Exception:
                        pass
                inject_msgs = []
                if utf8_healed:
                    if _sync_builtin_fn:
                        try:
                            _sync_builtin_fn(silent=True)
                        except Exception:
                            pass
                    inject_msgs.append("[SKILLSDB SELF-HEALING: Restored Windows UTF-8 application manifests after mid-session Antigravity IDE update]")
                if need_routing_refresh and routing_dec:
                    inject_msgs.append(format_hook_routing_banner(routing_dec).strip())
                if need_drift_guard:
                    proj_flag = f' --project "{root_path}"' if root_path else ""
                    inject_msgs.append(
                        f"[SKILLSDB TURN-ECONOMY & DRIFT GUARD (Step {max_step})]:\n"
                        "1. NO SALAMI-SLICING: Read files <= 800 lines in 1 call; for > 800 lines, locate lines via grep/script first and batch all read_file calls in parallel within a single turn.\n"
                        "2. SUBAGENT FIREWALL & ZERO POLLING: Delegate open multi-file debugging (>= 4 search steps or > 5 files) to invoke_subagent ('research'), fix entire bug classes at once ('build && test'), and never poll 'manage_task status'.\n"
                        f"3. PROJECT MEMORY (.agents/memory.db): Persist discovered file structures, class/method mappings, and line offsets via 'skillsdb mem-save-fact <key> <value>{proj_flag}' and track work items via 'skillsdb mem-task-add <title>{proj_flag}' so context compaction never forces re-reading files."
                    )
                    rehydrated_lines, facts_cnt = _collect_project_memory_lines()
                    if rep_file or (has_valid_workspace and max_step >= 25 and facts_cnt < 5):
                        warn_detail = f"Repeated reads detected on {rep_file}!" if rep_file else f"Only {facts_cnt} facts currently stored in .agents/memory.db!"
                        inject_msgs.append(
                            f"[PROJECT MEMORY ALERT: {warn_detail} Immediately save key file line ranges, class/method roles, and architectural findings via 'skillsdb mem-save-fact <key> <value>{proj_flag}' so you do not re-read the same files after context compaction!]"
                        )
                    if rehydrated_lines:
                        inject_msgs.append("=== PROJECT MEMORY CONTEXT (Auto-Hydrated from .agents/memory.db) ===\n" + "\n".join(rehydrated_lines))
                if inject_msgs:
                    print(json.dumps({
                        "injectSteps": [{
                            "ephemeralMessage": "\n".join(inject_msgs)
                        }]
                    }))
                else:
                    print(json.dumps({"injectSteps": []}))
                return
            state[cid] = dedup_token
            state[f"{cid}:drift_bucket"] = epoch_info.get("step_bucket", 0)
            if current_routing_sig:
                state[f"{cid}:routing_sig"] = current_routing_sig
            if len(state) > 100:
                keys = list(state.keys())[-50:]
                state = {k: state[k] for k in keys}
            _HOOK_STATE_FILE.write_text(json.dumps(state), encoding="utf-8")
        except Exception:
            pass

    if _sync_builtin_fn:
        try:
            _sync_builtin_fn(silent=True)
        except Exception:
            pass

    tier, tdesc = detect_model_tier(cid=cid, model_name_hint=model_hint)
    lines = []
    if utf8_healed:
        lines.append("[SKILLSDB SELF-HEALING: Restored Windows UTF-8 application manifests after Antigravity IDE update]")

    # 0. Global Turn-1 Invariant Guardrails (Strict English for maximum LLM attention weight & adherence)
    guardrail_lines = [
        "[SKILLSDB CRITICAL GUARDRAIL & INVARIANTS (TURN 1)]",
        "MANDATORY OPERATIONAL DIRECTIVES FOR ALL CONVERSATION TURNS:",
        "1. STRICT LANGUAGE SEPARATION & TYPOGRAPHY (ZERO TOLERANCE):",
        "   - Conversational Chat: Strictly informal German (\"Du\"/\"Dein\" for the user, and \"wir\"/\"unser\" for our joint work; strictly NEVER formal \"Sie\" and NEVER plural \"Ihr\"/\"Euer\"/\"Eurer\"/\"Euch\", as there are only the two of us; natural spelling with umlauts: ä, ö, ü, ß).",
        "   - Code, Artifacts & UI: 100% English (ASCII only). ALL code, comments, console outputs, logs, UI labels, buttons, dialogs, user-facing error strings, and commit messages MUST BE IN GRAMMATICALLY CORRECT ENGLISH. NEVER translate UI dialogs, labels, or buttons to German, even when conversing in German.",
        "   - Clean Typography: Strictly NO em-dashes (Unicode U+2014) or en-dashes (Unicode U+2013); always use standard ASCII hyphens (-), colons (:), or parentheses. Strictly NO emojis.",
        "   - Sentence Case: Always use natural sentence case for headings, subheadings, and bold bullet labels (never newspaper-style Title Case).",
        "   - German Orthography: Strictly NO 'Deppenbindestriche' in German compound words (e.g. write 'Abteilungskontingent' never 'Abteilungs-Kontingent', 'Kontextkompaktierung' never 'Kontext-Kompaktierung').",
        "2. AUTONOMOUS PROJECT MEMORY, GITEA SYNC & CONTINUITY:",
        "   - On any non-trivial technical task or workspace: Silently initialize/inspect project memory ('skillsdb mem-get-context' or 'skillsdb mem-init') and query domain skills ('skillsdb suggest \"<task>\"') without waiting for user prompting.",
        "   - Mandatory Fact, Offset & Task Indexing (.agents/memory.db): Immediately persist discovered file structures, class/method mappings, and line offsets via 'skillsdb mem-save-fact <key> <value> --project <dir>' and track multi-step tasks via 'skillsdb mem-task-add <title> --project <dir>', alongside architectural decisions ('skillsdb mem-save-decision') and milestone snapshots ('skillsdb mem-save-snapshot'), so context compaction never causes repeated file reads.",
        "   - Local Git & Optional Gitea Sync: SkillsDB works 100% standalone with local Git and .agents/memory.db even when Gitea is not installed. When local Gitea is configured (or requested by the user), use 'skillsdb gitea-init \"<target_dir>\"' or 'skillsdb gitea-sync -m \"<msg>\" --project \"<target_dir>\" [--releases] [--github]' (or 'skillsdb gitea-release' / 'skillsdb gitea-status') without manual token hunting. Always author commits as 'Antigravity <antigravity@local.dev>' and format Gitea/GitHub URLs as clickable Markdown links.",
        "   - Strict SemVer 2.0.0 & Keep a Changelog 1.1.0: Always version according to https://semver.org/ (MAJOR.MINOR.PATCH) and format CHANGELOG.md and releases strictly according to https://keepachangelog.com/en/1.1.0/ ('## [X.Y.Z] - YYYY-MM-DD' with only '### Added', '### Changed', '### Deprecated', '### Removed', '### Fixed', '### Security'). Never overwrite an existing release tag; increment VERSION + CHANGELOG.md and publish matching Git tags/releases (to local Git, and to Gitea/GitHub when configured).",
        "   - Gitea Repository Collision Guard: If 'skillsdb gitea-init' or 'skillsdb gitea-sync' outputs '[GITEA REPOSITORY COLLISION]', or if Git Telemetry shows '[GITEA COLLISION ALERT]' (an unlinked local workspace whose name already exists on Gitea), STOP immediately and ask the user in informal German how to proceed before pushing: reuse the existing repository (--use-existing), create it under a new name (--name <NewName>), or overwrite it (--overwrite).",
        "3. VERIFICATION INTEGRITY & PROACTIVE ERROR REPORTING:",
        "   - Never deliver untested code, broken shortcuts, or unverified event listeners. Always verify DOM and UI behavior in a real or simulated harness (e.g. jsdom / test harness) before declaring success.",
        "   - Tooling Anomaly Note (No Recurring Silent Workarounds): If an internal AntiGraviton/SkillsDB command, hook, or Gitea/GitHub sync exhibits a bug that forces a manual workaround in the background, finish the task first and add a brief note at the end of your response suggesting a root-cause fix in AntiGraviton.",
        "4. TURN-ECONOMY, PARALLEL BATCHING & DIAGNOSTIC PROTOCOL (MANDATORY):",
        "   - Anti-Salami-Slicing (Read Budget): Read files <= 800 lines completely in 1 call. For files > 800 lines, locate exact line numbers via grep/script first and batch all read_file calls in parallel within a single turn. Never slice a file across sequential 80-120 line turns.",
        "   - Subagent Firewall (invoke_subagent): Solve known 1-3 file fixes and targeted single-host / remote WMI / CIM / system admin diagnostics directly in the main context. Delegate open-ended local codebase root-cause hunting (>= 4 search steps) or scanning > 5 local files to a 'research' subagent (returning exact file paths, line numbers, and root cause) so search noise never bloats the main context.",
        "   - Cluster-Fix & Chained Pipelines: When a bug pattern is found, check the entire project for all occurrences of that bug class before rebuilding, and chain build/test/verify into one command ('build && test && verify').",
        "   - Zero-Polling & Local Indexing: Use WaitMsBeforeAsync=5000-10000 for fast commands; when a task backgrounds, NEVER poll 'manage_task status' (wait for automatic Reactive Wakeup). For codebases > 300 files requiring >= 3 analysis rounds, build a local SQLite index in scratch/ instead of repeated brute-force file scans.\n"
    ]
    lines.append("\n".join(guardrail_lines))

    # 0.5 Temporal Epoch Slicing & Cross-Project Isolation Anchor
    today_utc = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    ws_display = f"{root_path.name} ({root_path})" if (has_valid_workspace and root_path) else "None (Global)"
    anchor_lines = [
        "[TEMPORAL & WORKSPACE ISOLATION ANCHOR]",
        f"Current Date (UTC): {today_utc} | Active Workspace: {ws_display}",
    ]
    if epoch_info["epoch_count"] > 1 and epoch_info["active_epoch"]:
        first_ep = epoch_info["epochs"][0]
        act_ep = epoch_info["active_epoch"]
        anchor_lines.append(
            f"Conversation Timeline: {epoch_info['epoch_count']} temporal epochs ({first_ep['date']} -> {act_ep['date']}) | "
            f"Active Epoch #{act_ep['epoch_index']} started {act_ep['date']} (steps {act_ep['step_start']}..{act_ep['step_end']}, {act_ep['turn_count']} user turns)"
        )
    if epoch_info["foreign_project_mentions"]:
        summary_items = [
            f"'{m['project']}' on {m['date']} (step {m['step_index']})"
            for m in epoch_info["foreign_project_mentions"][:5]
        ]
        ws_short = root_path.name if (has_valid_workspace and root_path) else "current session"
        anchor_lines.append(
            f"[CROSS-PROJECT CONTAMINATION GUARD]: Earlier epochs in this conversation ID (and <CONTEXT_SUMMARY>) mention foreign workspace(s): "
            f"{', '.join(summary_items)}. Those prompts belong to historical sessions on earlier dates. "
            f"Do NOT attribute them to today's date ({today_utc}) or mix their architecture/facts with active workspace '{ws_short}'."
        )
    anchor_lines.append("")
    lines.append("\n".join(anchor_lines))

    if tier == TIER_ULTRA:
        lines.append("[SKILLSDB RUNTIME PROFILE: GEMINI ULTRA (16-thread high-concurrency mode)]")
        lines.append("Parallel batch fetching active: 'skillsdb get-skills <s1> <s2>' | Clusters: 'skillsdb get-cluster <domain>' | Parallel search: 'skillsdb search-multi <q1> <q2>' | Concurrent subagents: 8-16 parallel workers supported.")
    try:
        routing_dec = compute_routing_decision(
            cid=cid,
            db_path=central_db_override,
            model_name_hint=model_hint,
            brain_dir=brain_dir_override,
        )
        lines.append(format_hook_routing_banner(routing_dec))
    except Exception:
        pass

    # Auto-initialize project memory and local Git repository if a valid project workspace is open and has files
    if has_valid_workspace and root_path and db_path:
        if root_path.exists():
            try:
                has_files = any(f for f in root_path.iterdir() if f.name not in (".agents", ".git"))
                if has_files:
                    if not db_path.exists():
                        with managed_connection(db_path, is_project_db=True) as conn:
                            init_project_db(conn)
                    if not _is_temp_workspace(root_path) and not (root_path / ".git" / "HEAD").exists():
                        setup_workspace_git(root_path, configure_remote=False)
            except Exception:
                pass

        learn_workspace(root_path)

    # 1. Autonomous Directory Scoping & Antigravity v2.28.0+ User Prompt Pre-Routing
    cwd_hints = detect_cwd_hints(proj_path) if has_valid_workspace else []
    user_msg = _extract_hook_user_message(payload)
    if (cwd_hints or user_msg) and DB_PATH.exists():
        try:
            with managed_connection(DB_PATH) as gconn:
                gcursor = gconn.cursor()
                query_terms = []
                if user_msg:
                    query_terms.extend(expand_query_with_synonyms(user_msg, gconn)[:10])
                for h in cwd_hints[:8]:
                    if h not in query_terms:
                        query_terms.append(h)
                matched_skills = []
                if query_terms:
                    fts_query = build_safe_fts_query(query_terms, max_terms=12)
                    if fts_query:
                        gcursor.execute("""
                        SELECT s.name, s.description FROM skills_fts f
                        JOIN skills s ON f.rowid = s.id
                        WHERE skills_fts MATCH ?
                        ORDER BY rank LIMIT 3;
                        """, (fts_query,))
                        matched_skills = gcursor.fetchall()
            if matched_skills:
                if cwd_hints:
                    lines.append(f"[AUTONOMOUS DIRECTORY SCOPING: {', '.join(cwd_hints)}]")
                else:
                    lines.append("[AUTONOMOUS PROMPT SKILL PRE-ROUTING (Turn 1)]")
                lines.append("Domain micro-skills pre-routed for current workspace:")
                for ms in matched_skills:
                    raw_desc = ms["description"] or ""
                    desc = raw_desc[:95] + "..." if len(raw_desc) > 95 else raw_desc
                    lines.append(f"  * {ms['name']}: {desc}")
                lines.append("")
        except Exception:
            pass

    mem_lines, _ = _collect_project_memory_lines()
    if mem_lines:
        lines.append("=== PROJECT MEMORY CONTEXT (Auto-Loaded via Hook) ===")
        lines.extend(mem_lines)

    if lines:
        context_msg = "\n".join(lines).strip()
        output = {
            "injectSteps": [
                {
                    "ephemeralMessage": context_msg
                }
            ]
        }
        print(json.dumps(output))
        return

    print(json.dumps({"injectSteps": []}))


def _compute_dynamic_turn_savings(conn: sqlite3.Connection = None, db_path: Path = DB_PATH) -> dict:
    """
    Dynamically computes per-turn prompt token savings and reduction percentage from the
    live rules and skills inventory in customizations.db instead of a static constant:
      - Unconsolidated rules baseline: SUM(token_estimate) of all active rules
      - Unconsolidated plugin catalog header: metadata/description tokens of all non-builtin skills
      - Unsliced full-skill context footprint: 2x average full skill body vs. surgical micro-sections
    """
    rules_tokens = 0
    catalog_tokens = 0
    avg_skill_tokens = 0
    total_skills_tokens = 0

    def _query(c: sqlite3.Connection):
        nonlocal rules_tokens, catalog_tokens, avg_skill_tokens, total_skills_tokens
        cur = c.cursor()
        cur.execute("SELECT COALESCE(SUM(token_estimate), 0) FROM rules WHERE is_active = 1;")
        rules_tokens = int(cur.fetchone()[0] or 0)
        cur.execute(
            "SELECT COALESCE(SUM(CAST((LENGTH(COALESCE(name, '')) + LENGTH(COALESCE(description, ''))) / 4 AS INT) + 28), 0) "
            "FROM skills WHERE is_active = 1 AND plugin_name != 'builtin';"
        )
        catalog_tokens = int(cur.fetchone()[0] or 0)
        cur.execute("SELECT COALESCE(CAST(AVG(token_estimate) AS INT), 0), COALESCE(SUM(token_estimate), 0) FROM skills WHERE is_active = 1;")
        row = cur.fetchone()
        if row:
            avg_skill_tokens = int(row[0] or 0)
            total_skills_tokens = int(row[1] or 0)

    try:
        if conn is not None:
            _query(conn)
        elif db_path and Path(db_path).exists():
            with managed_connection(Path(db_path)) as tmp_conn:
                _query(tmp_conn)
    except Exception:
        pass

    raw_turn_baseline = rules_tokens + catalog_tokens + (avg_skill_tokens * 2)
    if raw_turn_baseline <= 500:
        raw_turn_baseline = 14810

    active_pointer_tokens = 380
    tokens_saved_per_turn = max(500, raw_turn_baseline - active_pointer_tokens)
    reduction_pct = round((tokens_saved_per_turn / float(raw_turn_baseline)) * 100.0, 1)

    return {
        "rules_tokens": rules_tokens,
        "catalog_tokens": catalog_tokens,
        "avg_skill_tokens": avg_skill_tokens,
        "total_skills_tokens": total_skills_tokens,
        "raw_turn_baseline": raw_turn_baseline,
        "active_pointer_tokens": active_pointer_tokens,
        "tokens_saved_per_turn": tokens_saved_per_turn,
        "reduction_pct": reduction_pct,
    }


def calculate_transcript_savings(
    target_date: str = None,
    brain_dir: Path = None,
    conn: sqlite3.Connection = None,
    db_path: Path = DB_PATH,
):
    """
    Scans Antigravity transcript files to compute both date-scoped (default: today UTC)
    and cumulative all-time prompt tokens avoided using dynamic database baselines.
    """
    b_dir = Path(brain_dir) if brain_dir else (resolve_user_home() / ".gemini" / "antigravity" / "brain")
    if not b_dir.exists():
        return None

    day_str = (target_date or datetime.now(timezone.utc).strftime("%Y-%m-%d"))[:10]

    total_turns = 0
    total_steps = 0
    session_count = 0

    day_turns = 0
    day_steps = 0
    day_sessions = 0

    for folder in b_dir.iterdir():
        if not folder.is_dir() or folder.name == "tempmediaStorage":
            continue
        t_file = folder / ".system_generated" / "logs" / "transcript.jsonl"
        if not t_file.exists():
            continue

        has_post_deploy = False
        has_day_activity = False
        s_turns = 0
        s_steps = 0
        s_day_turns = 0
        s_day_steps = 0

        try:
            with open(t_file, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    d = json.loads(line)
                    s_steps += 1
                    ts = str(d.get("created_at") or "")
                    if ts >= "2026-09-18T14:00:00Z":
                        has_post_deploy = True
                    is_day = ts.startswith(day_str)
                    if is_day:
                        has_day_activity = True
                        s_day_steps += 1
                    src = d.get("source")
                    stype = d.get("type")
                    if src == "MODEL" or stype == "PLANNER_RESPONSE":
                        s_turns += 1
                        if is_day:
                            s_day_turns += 1
            if has_post_deploy:
                session_count += 1
                total_steps += s_steps
                total_turns += s_turns
            if has_day_activity:
                day_sessions += 1
                day_steps += s_day_steps
                day_turns += s_day_turns
        except Exception:
            pass

    if total_turns == 0 and day_turns == 0:
        return None

    dyn = _compute_dynamic_turn_savings(conn=conn, db_path=db_path)
    per_turn = dyn["tokens_saved_per_turn"]
    reduction_pct = dyn["reduction_pct"]

    tokens_saved = total_turns * per_turn
    dollars_saved_pro = (tokens_saved / 1_000_000) * 2.00
    dollars_saved_ultra = (tokens_saved / 1_000_000) * 7.50

    day_tokens_saved = day_turns * per_turn
    day_dollars_pro = (day_tokens_saved / 1_000_000) * 2.00
    day_dollars_ultra = (day_tokens_saved / 1_000_000) * 7.50

    return {
        "sessions": session_count,
        "model_turns": total_turns,
        "steps": total_steps,
        "tokens_saved": tokens_saved,
        "tokens_saved_per_turn": per_turn,
        "unbundled_turn_baseline": dyn["raw_turn_baseline"],
        "reduction_pct": reduction_pct,
        "dollars_saved": dollars_saved_pro,
        "dollars_saved_pro": dollars_saved_pro,
        "dollars_saved_ultra": dollars_saved_ultra,
        "target_date": day_str,
        "day_sessions": day_sessions,
        "day_model_turns": day_turns,
        "day_steps": day_steps,
        "day_tokens_saved": day_tokens_saved,
        "day_dollars_pro": day_dollars_pro,
        "day_dollars_ultra": day_dollars_ultra,
    }


def stats(conn: sqlite3.Connection, show_savings: bool = False, target_date: str = None):
    """Outputs database inventory stats and both date-scoped and cumulative token/cost savings."""
    cursor = conn.cursor()
    cursor.execute("SELECT COUNT(*) as count, SUM(token_estimate) as tokens FROM rules;")
    r_stat = cursor.fetchone()
    cursor.execute("SELECT COUNT(*) as count, SUM(token_estimate) as tokens FROM skills;")
    s_stat = cursor.fetchone()

    print("\n================ CUSTOMIZATIONS DATABASE STATS ================")
    print(f"Database Path: {DB_PATH}")
    print(f"Rules:         {r_stat['count']} rules (Active content: ~{r_stat['tokens']} tokens)")
    print(f"Skills:        {s_stat['count']} skills (Total content: ~{s_stat['tokens']} tokens)")

    savings = calculate_transcript_savings(target_date=target_date, conn=conn)
    if savings:
        day_lbl = savings["target_date"]
        red_pct = savings["reduction_pct"]
        print(
            f"Turn Baseline: ~{savings['unbundled_turn_baseline']:,} raw tokens/turn -> "
            f"~{savings['tokens_saved_per_turn']:,} tokens saved/turn (-{red_pct:.1f}%)"
        )
        print(f"\n--- Measured Activity for {day_lbl} (Strictly Date-Scoped) ---")
        print(f"Active Sessions ({day_lbl}): {savings['day_sessions']} sessions")
        print(f"Model Turns ({day_lbl}):     {savings['day_model_turns']:,} turns ({savings['day_steps']:,} steps)")
        print(f"Prompt Bloat Avoided:         ~{savings['day_tokens_saved']:,} tokens (-{red_pct:.1f}% per turn)")
        print(f"Cost Saved (Gemini Pro):      ~${savings['day_dollars_pro']:.2f} USD")
        print(f"Cost Saved (Gemini Ultra):    ~${savings['day_dollars_ultra']:.2f} USD")

        print("\n--- Cumulative Token Savings (Since SkillsDB Deployment) ---")
        print(f"Tracked Sessions:     {savings['sessions']} active sessions")
        print(f"Total Model Turns:    {savings['model_turns']:,} turns ({savings['steps']:,} steps)")
        print(f"Prompt Bloat Avoided: ~{savings['tokens_saved']:,} tokens (-{red_pct:.1f}% per turn)")
        print(f"Cost Saved (Gemini Pro):   ~${savings['dollars_saved_pro']:.2f} USD")
        print(f"Cost Saved (Gemini Ultra): ~${savings['dollars_saved_ultra']:.2f} USD")
        minfo = detect_model_and_pool()
        acc_tier = minfo.get("account_tier", "ultra")
        if acc_tier == "ultra" or minfo.get("model_tier") == TIER_ULTRA:
            print(
                f"Active Profile:       ULTRA [Model: {minfo['model_name']} | Pool: {minfo['pool']}] "
                f"(~${savings['dollars_saved_ultra']:.2f} USD saved / 16-thread high concurrency)"
            )
        else:
            print(
                f"Active Profile:       PRO [Model: {minfo['model_name']} | Pool: {minfo['pool']}] "
                f"(~${savings['dollars_saved_pro']:.2f} USD saved / 8-thread Golden-Ratio protection)"
            )
    try:
        l24 = get_ledger_24h_summary(db_path=DB_PATH)
        if l24["saved_agy_tokens_total"] > 0 or l24["subagent_24h_rewrites"] > 0:
            print("\n--- Multi-Pool Quota Router & External Offload Savings ---")
            print(f"24h External Offloads: CLI-OAuth={l24['cli_24h_requests']}, AIStudio-API={l24['aistudio_24h_requests']}, Web-Handovers={l24['web_24h_handovers']}, Subagent-Rewrites={l24['subagent_24h_rewrites']}")
            print(f"Offload Quota Saved:   ~{l24['saved_agy_tokens_total']:,} AGY tokens ({l24['saved_agy_turns_total']} turns avoided)")
    except Exception:
        pass
    print(f"[OK] Version: v{__version__} (Up to date)")
    print("================================================================\n")


